  // True when the guest bytes [address, address + size) are mapped readable
  // (logs 175 / 180: diagnostics followed name pointers out of destroyed
  // props, 0x3F800000 / 0x03030000, and crashed on unmapped pages).
  bool Readable(const uint8_t *base, uint32_t address, uint32_t size)
  {
    if (address < 0x00010000u || address > 0xFFFF0000u - size)
    {
      return false;
    }
    size_t length = size;
    rex::memory::PageAccess access = rex::memory::PageAccess::kNoAccess;
    return rex::memory::QueryProtect(const_cast<uint8_t *>(base) + address, length, access) &&
           (uint32_t(access) & uint32_t(rex::memory::PageAccess::kReadOnly)) != 0 && length >= size;
  }

  std::string ReadString(const uint8_t *base, uint32_t address, size_t max = 128)
  {
    std::string text;
    if (!Readable(base, address, uint32_t(max)))
    {
      return text;
    }
    for (size_t i = 0; address && i < max && base[address + i]; ++i)
    {
      text += char(base[address + i]);
    }
    return text;
  }

  int32_t Call(PPCContext &ctx, uint8_t *base, PPCFunc *fn, uint32_t r3, uint32_t r4 = 0, uint32_t r5 = 0)
  {
    rex::CallFrame frame(ctx);
    frame.ctx.r3.u64 = r3;
    frame.ctx.r4.u64 = r4;
    frame.ctx.r5.u64 = r5;
    fn(frame.ctx, base);
    return int32_t(frame.ctx.r3.u32);
  }

  // Set while ScenarioList reads the game's list: the readers call each other
  // (value at index and last call count), so those calls must get the game's
  // own answers, not ours (endless recursion otherwise).
  thread_local bool t_reading_list = false;

  // Whether the setup's level (the LEVEL option) is one of these.
  template <size_t N> bool LevelIn(PPCContext &ctx, uint8_t *base, const uint32_t (&levels)[N])
  {
    const int32_t level = Call(ctx, base, __imp__sub_823B8340, kOptionLevel);
    bool found = false;
    std::string seen;
    for (uint32_t name : levels)
    {
      const int32_t value = Call(ctx, base, __imp__sub_823BB108, name);
      found |= level >= 0 && value == level;
      seen += " " + std::to_string(value);
    }
    // Diagnostic: once per change of level / answer.
    static int32_t last_level = -2;
    static std::string last_seen;
    if (Log() && (level != last_level || seen != last_seen))
    {
      last_level = level;
      last_seen = seen;
      REXLOG_INFO("pdz_scenario: list check: LEVEL {} vs maps{} -> {}", level, seen, found ? "yes" : "no");
    }
    return found;
  }

  // Defined with the map rules ("The scenario decides the maps", below).
  std::vector<int32_t> RareScenarios(const uint8_t *base, uint32_t option);
  bool ScenarioOnMap(PPCContext &ctx, uint8_t *base, uint32_t option, int32_t scenario, int32_t position);

  // Set while Rare's validation of one option (sub_823BC658) runs.
  thread_local bool t_validating = false;

  // The scenario list: every scenario Rare offers on any map (both of its
  // per-map lists) plus ours (Plant the Flag and Protection; Duel only with
  // pdz_mp_cut_scenarios_duel: its round award filled in, untested), in value order, whatever
  // the map; the LEVEL list then offers only the maps the scenario supports.
  // Rare's validation (a level change, settings load, match setup) sees only
  // the scenarios the current map supports, so it still resets a scenario
  // the map can't host (the safety net).
  std::vector<int32_t> ScenarioList(PPCContext &ctx, uint8_t *base, uint32_t option)
  {
    struct Guard
    {
      Guard() { t_reading_list = true; }
      ~Guard() { t_reading_list = false; }
    } guard;
    std::vector<int32_t> list = RareScenarios(base, option);
    if (list.empty())
    {
      // Rare's lists not loaded: the game's list for this map.
      const int32_t count = Call(ctx, base, __imp__sub_823BB748, option);
      for (int32_t i = 0; i >= 0 && i < count && i < 32; ++i)
      {
        list.push_back(Call(ctx, base, __imp__sub_823BBD30, option, uint32_t(i), 0));
      }
    }
    const auto has = [&](int32_t value) { return std::find(list.begin(), list.end(), value) != list.end(); };
    // Always offered, in value order: the scenario decides the maps, not the
    // other way round (see "The scenario decides the maps" below).
    const auto add = [&](int32_t value)
    {
      if (!has(value))
      {
        list.insert(std::upper_bound(list.begin(), list.end(), value), value);
      }
    };
    if (option == kOptionScenario)
    {
      add(kPlantTheFlag);
      add(kProtection);
    }
    else if (REXCVAR_GET(pdz_mp_cut_scenarios_duel))
    {
      add(kDuel);
    }
    if (t_validating)
    {
      const int32_t level = Call(ctx, base, __imp__sub_823B8340, kOptionLevel);
      std::vector<int32_t> supported;
      for (int32_t value : list)
      {
        if (ScenarioOnMap(ctx, base, option, value, level))
        {
          supported.push_back(value);
        }
      }
      if (!supported.empty())
      {
        list = std::move(supported);
      }
    }
    // Diagnostic: once per change.
    static std::string last[2];
    std::string text;
    for (int32_t v : list)
    {
      text += " " + std::to_string(v);
    }
    std::string &previous = last[option == kOptionScenario ? 0 : 1];
    if (Log() && text != previous)
    {
      previous = text;
      REXLOG_INFO("pdz_scenario: list option {}:{}", option, text);
    }
    return list;
  }

  bool Ours(uint32_t option)
  {
    return (option == kOptionScenario || option == kOptionDarkOpsScenario) && Enabled() && !t_reading_list;
  }

