// sub_8244AEB8 [8243EE20](mode): its per-frame update.
void PdzPlantTheFlagBots(PPCContext &ctx, uint8_t *base);

REX_HOOK_RAW(sub_8244AEB8)
{
  if (Log() && !g_ticked)
  {
    g_ticked = true;
    const uint8_t *p = base + ctx.r3.u32 + 308;
    REXLOG_INFO("pdz_scenario: Plant the Flag mode {:08X} first update (plant time {})", ctx.r3.u32,
                (uint32_t(p[0]) << 24) | (uint32_t(p[1]) << 16) | (uint32_t(p[2]) << 8) | p[3]);
  }
  const uint32_t mode = ctx.r3.u32;
  PPCContext entry = ctx;
  if (Enabled() && mode == g_mode)
  {
    PdzPlantTheFlagBots(ctx, base); // our bots (end of file)
  }
  __imp__sub_8244AEB8(ctx, base);
  if (Enabled() && mode == g_mode)
  {
    mp_announcer::PlantTheFlagTick(entry, base, mode); // plant starts, enemy planted
  }
}

