// CP3 (log 152): DEMOKIT_DETACH cues seen (a planted charge left the kit).
int g_demokit_detaches = 0;

REX_HOOK_RAW(sub_82202D20)
{
  minigame_log::OnCue(ctx, base, ctx.r4.u32);
  if (ctx.r4.u32 && std::strstr(reinterpret_cast<const char *>(base + ctx.r4.u32), "DEMOKIT_DETACH"))
  {
    ++g_demokit_detaches;
  }
  // Recorded lines under other names (cue_fixes.cpp, game fixes), unused
  // announcer lines (mp_announcer.cpp), Protection's hacker-down line.
  ctx.r4.u64 = cue_fixes::CueName(ctx, base, ctx.r4.u32);
  ctx.r4.u64 = mp_announcer::CueName(ctx, base, ctx.r4.u32);
  ctx.r4.u64 = PdzProtectionCueName(base, ctx.r4.u32);
  if (Log())
  {
    // Log 147 / 150: Sabotage isn't a cut scenario match, so its plant cues
    // (DO_EXPLOSIVES_SET, DEMOKIT_*) are logged by name in any mode.
    // Logs 192-214 (frame drops since the 12:55 build): ReadString asks
    // Windows whether the memory is readable (QueryProtect, added for the
    // log 180 crash), and this hook sees every cue by name, ~2,900 a second:
    // ~1,000 ms/s of host time in the profile (pdz_hook_profile, log 214). The
    // game's own cue name is read directly here.
    const uint32_t at = ctx.r4.u32;
    const std::string_view name =
        at >= 0x10000u && at < 0x90000000u ? std::string_view(reinterpret_cast<const char *>(base + at),
                                              strnlen(reinterpret_cast<const char *>(base + at), 128))
                           : std::string_view();
    if ((name.rfind("XACT_SOUNDBANK_MULTIPLAYER_", 0) == 0 && (g_mode || PdzCutScenarioMatch(base))) ||
        name.find("EXPLOSIVES") != std::string_view::npos || name.find("DEMOKIT") != std::string_view::npos)
    {
      REXLOG_INFO("pdz_scenario: announcer cue {}", name);
    }
  }
  __imp__sub_82202D20(ctx, base);
}

