namespace
{
  constexpr uint32_t kMatchSettings = 0x82E2FB20; // -> match settings
  constexpr uint32_t kSettingsMode = 4404;        // byte: 0 Deathmatch, 1 DarkOps
  constexpr uint32_t kSettingsScenario = 4414;    // byte: Deathmatch scenario

  constexpr uint32_t kBotVtable = 0x820BF3B8;     // bot character class
  constexpr uint32_t kCharacterParticipant = 668; // character vtable: its participant
  constexpr uint32_t kPosition = 48;              // character / base: position (vec3)
  constexpr uint32_t kFlagHolder = 964;           // flag object: character carrying it

  constexpr uint32_t kBrainTeam = 4;              // team brain: its team
  constexpr uint32_t kBrainTarget = 48;           // team brain: target team

  constexpr uint32_t kModeBases = 4;              // mode: base object per team (4)
  constexpr uint32_t kModePlantTime = 308;        // mode: hold needed

  constexpr uint32_t kCarrierTeamReturn1 = 0x821C5978; // goal 5: base to carry to
  constexpr uint32_t kCarrierTeamReturn2 = 0x821C59E4;
  // Plant zone, cm from the enemy base: a bot starts planting within
  // kPlantEnter and keeps planting until it is beyond kPlantLeave or out of
  // the zone for kPlantGrace (combat strafing). The goal-5 destination pad
  // is ~2.45 m from the base, so a 2.5 m edge (first build) kept resetting.
  constexpr float kPlantEnter = 300.0f;
  constexpr float kPlantLeave = 450.0f;
  constexpr double kPlantGrace = 2.0;                  // seconds
  constexpr int kTeams = 4;

  uint32_t Load32(const uint8_t *base, uint32_t address)
  {
    const uint8_t *p = base + address;
    return (uint32_t(p[0]) << 24) | (uint32_t(p[1]) << 16) | (uint32_t(p[2]) << 8) | p[3];
  }

  void Store32(uint8_t *base, uint32_t address, uint32_t value)
  {
    uint8_t *p = base + address;
    p[0] = uint8_t(value >> 24);
    p[1] = uint8_t(value >> 16);
    p[2] = uint8_t(value >> 8);
    p[3] = uint8_t(value);
  }

  float LoadFloat(const uint8_t *base, uint32_t address)
  {
    const uint32_t bits = Load32(base, address);
    float value;
    std::memcpy(&value, &bits, sizeof(value));
    return value;
  }

  void StoreFloat(uint8_t *base, uint32_t address, float value)
  {
    uint32_t bits;
    std::memcpy(&bits, &value, sizeof(bits));
    Store32(base, address, bits);
  }

  bool IsGuestPointer(uint32_t address)
  {
    return address >= 0x00010000u && address < 0xFFFF0000u;
  }

  // A Plant the Flag match with the option on (also before the mode exists).
  bool PlantTheFlagMatch(const uint8_t *base)
  {
    if (!Enabled())
    {
      return false;
    }
    const uint32_t settings = Load32(base, kMatchSettings);
    return IsGuestPointer(settings) && base[settings + kSettingsMode] == 0 &&
           base[settings + kSettingsScenario] == kPlantTheFlag;
  }

  bool PlantTheFlagRunning()
  {
    return Enabled() && g_mode;
  }

  bool IsBot(const uint8_t *base, uint32_t character)
  {
    return IsGuestPointer(character) && Load32(base, character) == kBotVtable;
  }

  uint32_t CallVirtual(PPCContext &ctx, uint8_t *base, uint32_t object, uint32_t slot)
  {
    // Vtables live in the image: anything else is not an object (a field the
    // other participant kind doesn't have read as one crashed the game).
    const uint32_t vtable = Load32(base, object);
    if (vtable < 0x82000000u || vtable >= 0x84000000u)
    {
      return 0;
    }
    PPCFunc *fn = pdz::GuestFunction(Load32(base, vtable + slot));
    if (!fn)
    {
      return 0;
    }
    rex::CallFrame frame(ctx);
    frame.ctx.r3.u64 = object;
    fn(frame.ctx, base);
    return frame.ctx.r3.u32;
  }

  uint32_t TeamBase(const uint8_t *base, int team)
  {
    return team >= 0 && team < kTeams ? Load32(base, g_mode + kModeBases + uint32_t(team) * 4) : 0;
  }

  // The enemy team whose base a team plants on: the first other team with a
  // base (two-team matches: the other team).
  int EnemyTeam(const uint8_t *base, int team)
  {
    for (int t = 0; t < kTeams; ++t)
    {
      if (t != team && IsGuestPointer(TeamBase(base, t)))
      {
        return t;
      }
    }
    return team;
  }

  float Distance(const uint8_t *base, uint32_t a, uint32_t b)
  {
    float d2 = 0.0f;
    for (uint32_t i = 0; i < 3; ++i)
    {
      const float d = LoadFloat(base, a + kPosition + i * 4) - LoadFloat(base, b + kPosition + i * 4);
      d2 += d * d;
    }
    return std::sqrt(d2);
  }

  // The match settings' scenario seen as Capture the Flag during a call.
  struct ScenarioAsCtf
  {
    uint8_t *base;
    uint32_t settings = 0;
    explicit ScenarioAsCtf(uint8_t *b) : base(b)
    {
      if (PlantTheFlagMatch(base))
      {
        settings = Load32(base, kMatchSettings);
        base[settings + kSettingsScenario] = uint8_t(kCaptureTheFlag);
      }
    }
    ~ScenarioAsCtf()
    {
      if (settings)
      {
        base[settings + kSettingsScenario] = uint8_t(kPlantTheFlag);
      }
    }
  };

  // A bot planting: since when it has been in the zone (host clock), and
  // whether the mode's own timing took it.
  struct BotPlant
  {
    bool in_zone = false;     // planting
    double held = 0.0;        // seconds planted
    double outside = 0.0;     // seconds out of the zone while planting
    std::chrono::steady_clock::time_point last;
    bool fallback_logged = false;
  };
  std::unordered_map<uint32_t, BotPlant> g_bot_plants;
  std::unordered_map<uint32_t, uint32_t> g_bot_goals;

  // Plant check (pdz_scenario_log; 2026-10-25: a carrier about to plant
  // ran off a bit and came back) and pdz_ptf_objective_focus. The bots
  // carrying their own team's flag (DriveBotPlants, every frame), with the
  // goal and brain activity last seen.
  struct PtfCarrier
  {
    int team = -1;
    uint32_t goal = 0xFFFFFFFFu;
    uint32_t activity = 0xFFFFFFFFu;
    std::chrono::steady_clock::time_point goal_sent{}; // our last goal-5 send (focus)
    std::chrono::steady_clock::time_point blocked_log{};
  };
  std::unordered_map<uint32_t, PtfCarrier> g_ptf_carriers;
  constexpr uint32_t kGoalCarry = 5;              // CTF goal: carry the flag (ours: to the enemy base)
  constexpr uint32_t kBotGoalField = 12976;       // bot: goal
  constexpr uint32_t kBrainActivityField = 56;    // bot brain: activity
  constexpr float kCarrierWatch = 1500.0f;        // cm: activity changes logged this near the enemy base

  bool PtfFocus()
  {
    return REXCVAR_GET(pdz_ptf_objective_focus) && PlantTheFlagRunning();
  }

  float EnemyBaseDistance(const uint8_t *base, uint32_t bot, int team)
  {
    const uint32_t enemy_base = TeamBase(base, EnemyTeam(base, team));
    return IsGuestPointer(enemy_base) ? Distance(base, bot, enemy_base) : -1.0f;
  }

  const char *GoalName(uint32_t goal)
  {
    static const char *kGoals[] = {"roam",       "1",           "2",          "attack carrier",
                                   "fetch flag", "carry",       "return flag", "guard base",
                                   "escort carrier"};
    return goal < 9 ? kGoals[goal] : "?";
  }

  const char *ActivityName(uint32_t activity)
  {
    static const char *kActivities[] = {"none",          "route",           "turn to look", "attack",
                                        "fetch weapon",  "fetch armour",    "side-step",    "dodge",
                                        "vehicle",       "vehicle spawner", "hack",         "revive",
                                        "goal-12 route", "dying"};
    return activity < 14 ? kActivities[activity] : "?";
  }

  // Who called Rare's goal setter (sub_82539AA0), by its return address.
  std::string GoalSetBy(uint32_t lr)
  {
    if (objective_bots::SettingGoal())
    {
      return "our code";
    }
    switch (lr)
    {
    case 0x8214ADE0:
      return "Rare's team brain (group 1)";
    case 0x8214AFEC:
      return "Rare's team brain (group 2)";
    case 0x8214B160:
      return "Rare's team brain (group 3)";
    case 0x821C5E34:
      return "Rare's goal planner (no plan)";
    case 0x821C4E40:
      return "Rare's chooser (dying)";
    case 0x821C1A08:
      return "Rare's teleporter hack (done)";
    case 0x8214A2F8:
      return "Rare's Sabotage brain (2 s reset)";
    default:
      return fmt::format("Rare's code (from {:08X})", lr);
    }
  }

  // Each frame (before the mode's tick): bots carrying their own flag into an
  // enemy base plant there.
  void DriveBotPlants(PPCContext &ctx, uint8_t *base)
  {
    const auto now = std::chrono::steady_clock::now();
    // A bot that no longer carries a flag (killed, flag returned) starts
    // over next time.
    uint32_t carriers[kTeams] = {};
    for (int team = 0; team < kTeams; ++team)
    {
      const uint32_t flag = uint32_t(Call(ctx, base, sub_8241D1E8, g_mode, uint32_t(team)));
      carriers[team] = IsGuestPointer(flag) ? Load32(base, flag + kFlagHolder) : 0;
    }
    for (auto &[bot, plant] : g_bot_plants)
    {
      if (std::find(std::begin(carriers), std::end(carriers), bot) == std::end(carriers))
      {
        if (plant.in_zone && Log())
        {
          REXLOG_INFO("pdz_scenario: plant check: bot {:08X} plant abandoned after {:.1f} s: no longer carrying the "
                      "flag ({})",
                      bot, plant.held, objective_bots::CharacterDown(ctx, base, bot) ? "died" : "flag dropped or taken");
        }
        plant.in_zone = false;
        plant.last = {};
      }
    }
    for (auto it = g_ptf_carriers.begin(); it != g_ptf_carriers.end();)
    {
      if (std::find(std::begin(carriers), std::end(carriers), it->first) == std::end(carriers))
      {
        if (Log())
        {
          REXLOG_INFO("pdz_scenario: plant check: bot {:08X} no longer carries its flag ({}), {:.1f} m from the enemy "
                      "base",
                      it->first, objective_bots::CharacterDown(ctx, base, it->first) ? "died" : "dropped or planted",
                      EnemyBaseDistance(base, it->first, it->second.team) / 100.0f);
        }
        it = g_ptf_carriers.erase(it);
        continue;
      }
      ++it;
    }
    for (int team = 0; team < kTeams; ++team)
    {
      const uint32_t holder = carriers[team];
      if (!IsBot(base, holder))
      {
        continue;
      }
      const int bot_team = Call(ctx, base, __imp__sub_8251CC10, holder);
      BotPlant &plant = g_bot_plants[holder];
      const int enemy = EnemyTeam(base, bot_team);
      const uint32_t enemy_base = TeamBase(base, enemy);
      const bool own_flag = team == bot_team;
      const float distance = IsGuestPointer(enemy_base) ? Distance(base, holder, enemy_base) : 1e9f;
      const double dt = plant.last.time_since_epoch().count() ? std::min(0.25, std::chrono::duration<double>(now - plant.last).count()) : 0.0;
      plant.last = now;
      const bool can_plant = own_flag && enemy != bot_team;
      if (own_flag)
      {
        // Plant check: the carrier's goal and activity (changes outside
        // Rare's setter too), and with the focus switch its carry goal.
        PtfCarrier &c = g_ptf_carriers[holder];
        if (c.team < 0 && Log())
        {
          REXLOG_INFO("pdz_scenario: plant check: bot {:08X} (team {}) carries its flag, {:.1f} m from team {}'s base, "
                      "goal {} ({})",
                      holder, bot_team, distance / 100.0f, enemy, int32_t(Load32(base, holder + kBotGoalField)),
                      GoalName(Load32(base, holder + kBotGoalField)));
        }
        c.team = bot_team;
        const uint32_t goal = Load32(base, holder + kBotGoalField);
        if (c.goal != 0xFFFFFFFFu && goal != c.goal && Log())
        {
          REXLOG_INFO("pdz_scenario: plant check: carrier {:08X} goal {} ({}) -> {} ({}) without Rare's setter, {:.1f} m "
                      "from the enemy base",
                      holder, int32_t(c.goal), GoalName(c.goal), int32_t(goal), GoalName(goal), distance / 100.0f);
        }
        c.goal = goal;
        const uint32_t brain = objective_bots::BrainOf(base, holder);
        const uint32_t activity = brain ? Load32(base, brain + kBrainActivityField) : 0xFFFFFFFFu;
        if (activity != c.activity && distance < kCarrierWatch && c.activity != 0xFFFFFFFFu && Log())
        {
          REXLOG_INFO("pdz_scenario: plant check: carrier {:08X} activity {} ({}) -> {} ({}), {:.1f} m from the enemy "
                      "base, goal {}{}",
                      holder, int32_t(c.activity), ActivityName(c.activity), int32_t(activity), ActivityName(activity),
                      distance / 100.0f, int32_t(goal), plant.in_zone ? ", planting" : "");
        }
        c.activity = activity;
        if (PtfFocus() && goal != kGoalCarry && !plant.in_zone && now - c.goal_sent >= std::chrono::seconds(1))
        {
          c.goal_sent = now;
          if (objective_bots::SetGoal(ctx, base, holder, kGoalCarry, 0) && Log())
          {
            REXLOG_INFO("pdz_scenario: plant check: carrier {:08X} back on goal 5 (carry) from goal {}, {:.1f} m from "
                        "the enemy base",
                        holder, int32_t(goal), distance / 100.0f);
          }
        }
      }
      if (!plant.in_zone)
      {
        if (!can_plant || distance >= kPlantEnter)
        {
          continue;
        }
        plant = BotPlant{true, 0.0, 0.0, now, false};
        mp_announcer::BotPlantStarted(ctx, base, bot_team);
        if (Log())
        {
          REXLOG_INFO("pdz_scenario: bot {:08X} (team {}) carrying flag {} entered team {}'s base ({:.0f} cm)", holder,
                      bot_team, team, enemy, distance);
        }
      }
      // Planting: brief exits (strafing, a fight) pause the timer.
      if (can_plant && distance < kPlantLeave)
      {
        plant.held += dt;
        plant.outside = 0.0;
      }
      else
      {
        plant.outside += dt;
      }
      if (!can_plant || distance >= kPlantLeave * 2 || plant.outside >= kPlantGrace)
      {
        if (Log())
        {
          const uint32_t brain = objective_bots::BrainOf(base, holder);
          REXLOG_INFO("pdz_scenario: plant check: bot {:08X} plant abandoned after {:.1f} s ({:.0f} cm from the base): "
                      "{}; goal {}, activity {}",
                      holder, plant.held, distance,
                      !can_plant                      ? "not its own flag"
                      : distance >= kPlantLeave * 2 ? "walked beyond 9 m"
                                                     : "out of the 4.5 m zone for 2 s",
                      int32_t(Load32(base, holder + kBotGoalField)),
                      brain ? ActivityName(Load32(base, brain + kBrainActivityField)) : "?");
        }
        plant.in_zone = false;
        continue;
      }
      const uint32_t participant = CallVirtual(ctx, base, holder, kCharacterParticipant);
      if (!IsGuestPointer(participant))
      {
        continue;
      }
      // Timed here: the mode's own hold slots (+304 / +68 / +72, by the
      // participant's +1652) belong to human players only; a bot's +1652 is
      // 0, the first player's slot (first test: the bot's plant was credited
      // to the player).
      const double needed = std::max(1.0, double(Load32(base, g_mode + kModePlantTime)) / 1000.0);
      if (!plant.fallback_logged && Log())
      {
        plant.fallback_logged = true;
        REXLOG_INFO("pdz_scenario: bot {:08X} planting ({:.1f} s)", holder, needed);
      }
      if (plant.held >= needed)
      {
        if (Log())
        {
          REXLOG_INFO("pdz_scenario: bot {:08X} plant complete after {:.1f} s", holder, plant.held);
        }
        rex::CallFrame frame(ctx);
        frame.ctx.r3.u64 = g_mode;
        frame.ctx.r4.u64 = uint32_t(enemy);
        frame.ctx.r5.u64 = participant;
        sub_8244C0A0(frame.ctx, base);
        plant.in_zone = false;
      }
    }
  }
} // namespace

void PdzPlantTheFlagBots(PPCContext &ctx, uint8_t *base)
{
  DriveBotPlants(ctx, base);
}

