uint32_t PdzProtectionBotsDeath(const uint8_t *base, uint32_t manager, uint32_t victim);

REX_HOOK_RAW(sub_82146A00)
{
  ScenarioAsCtf as_ctf(base);
  // Protection bots (pdz_protection_bots) would get the Capture the Flag bot
  // script, whose goals (escort / attack carrier) the objective toolkit
  // steers. OFF (kProtectionCtfScript): a Protection match with it crashed at
  // the start on a null read (log 055), most likely the script without a
  // flag mode or team brain; bots keep Rare's script until bot steering is
  // built on something Protection has.
  constexpr bool kProtectionCtfScript = false;
  const uint32_t protection =
      kProtectionCtfScript && PdzProtectionBots(base) ? Load32(base, kMatchSettings) : 0;
  if (protection)
  {
    base[protection + kSettingsScenario] = uint8_t(kCaptureTheFlag);
    if (Log())
    {
      REXLOG_INFO("pdz_scenario: Protection bots get the Capture the Flag bot script");
    }
  }
  struct Restore
  {
    uint8_t *base;
    uint32_t settings;
    ~Restore()
    {
      if (settings)
      {
        base[settings + kSettingsScenario] = uint8_t(kProtection);
      }
    }
  } restore{base, protection};
  if (as_ctf.settings && Log())
  {
    REXLOG_INFO("pdz_scenario: Plant the Flag bots get the Capture the Flag bot script");
  }
  constexpr uint32_t kSettingsDarkOpsScenario = 4434;
  const uint32_t settings = PdzDuelMatch(base) ? Load32(base, kMatchSettings) : 0;
  if (settings)
  {
    base[settings + kSettingsDarkOpsScenario] = 0;
    if (Log())
    {
      REXLOG_INFO("pdz_scenario: Duel bots get the DarkOps bot script (38)");
    }
  }
  __imp__sub_82146A00(ctx, base);
  if (settings)
  {
    base[settings + kSettingsDarkOpsScenario] = uint8_t(kDuel);
  }
}

