// --- Plant the Flag spawns (pdz_ptf_spawn) ---
// Rare's: every life starts in the team's armory (the spawn room under the
// map, while settings +4430 is set): pick weapons, take the teleporter, and
// it puts the player on the team's spawn pads at its base (sub_82436938
// [8242AB48], the room's destination per participant index at +1376 * 4).
// Defenders then appear on top of a planter (Tower, Trench). random: the
// match's first trip goes to the base as Rare's; after that the teleporter's
// destination is a random free-for-all (group 0) spawn pad with nobody within
// kNobodyNear and no flag base within kBaseClear. Too few such pads, or a map
// in kNoRandomSpawnMaps: Rare's. The sign above the teleporter still shows the
// team's own destination (map data).

REX_EXTERN(__imp__sub_82436938);

namespace
{
  constexpr uint32_t kSettingsTeams = 4410;       // byte: team count
  constexpr uint32_t kSettingsMap = 596;          // replicated value: map id
  constexpr uint32_t kPadManager = 0x82D6C068;    // -> pad manager
  constexpr uint32_t kPadSpawnList = 1100;        // pad manager: spawn pads (count, entries)
  constexpr uint32_t kPadEntrySize = 820;         // entry: +0 node, +4 group
  constexpr uint32_t kNodePosition = 16;          // node: position (vec3)
  constexpr uint32_t kParticipantCharacter = 964; // participant: its character
  constexpr uint32_t kParticipantIndex = 1008;    // participant: its index
  constexpr uint32_t kParticipantList = 0x82E34224; // -> first participant (+4 next)
  constexpr uint32_t kRoomDestinations = 1376 * 4;  // room: destination node per participant index
  constexpr float kBaseClear = 1500.0f;           // cm: no spawn this close to a flag base
  constexpr float kNobodyNear = 2000.0f;          // cm: as Rare's free-for-all chooser
  constexpr uint32_t kMinRandomPads = 8;
  constexpr uint32_t kNoRandomSpawnMaps[] = {0x21, 0x23}; // Facility, Ruin: no bases / team pads

  std::unordered_map<uint32_t, int> g_ptf_trips; // participant -> teleporter trips this match
  uint32_t g_ptf_trips_mode = 0;

  bool RandomSpawns(const uint8_t *base)
  {
    return PlantTheFlagMatch(base) && g_mode && REXCVAR_GET(pdz_ptf_spawn) == "random";
  }

  float DistanceTo(const uint8_t *base, uint32_t position, const float (&to)[3])
  {
    float d2 = 0.0f;
    for (int i = 0; i < 3; ++i)
    {
      const float d = LoadFloat(base, position + uint32_t(i) * 4) - to[i];
      d2 += d * d;
    }
    return std::sqrt(d2);
  }

  // Nearest flag base to a position (cm), or -1 with no bases.
  float NearestBase(const uint8_t *base, uint32_t position)
  {
    float best = -1.0f;
    for (int team = 0; team < kTeams; ++team)
    {
      const uint32_t flag_base = TeamBase(base, team);
      if (!IsGuestPointer(flag_base))
      {
        continue;
      }
      const float at[3] = {LoadFloat(base, flag_base + kPosition), LoadFloat(base, flag_base + kPosition + 4),
                           LoadFloat(base, flag_base + kPosition + 8)};
      const float d = DistanceTo(base, position, at);
      best = best < 0.0f ? d : std::min(best, d);
    }
    return best;
  }

  struct PadChoice
  {
    uint32_t node = 0;
    uint32_t eligible = 0; // group-0 pads clear of the bases
    uint32_t total = 0;    // group-0 pads
    bool listed = false;
  };

  // A random group-0 spawn pad clear of the flag bases, preferring one with
  // nobody near; none when too few pads qualify.
  PadChoice ChooseRandomPad(PPCContext &ctx, uint8_t *base, uint32_t self)
  {
    PadChoice choice;
    const uint32_t settings = Load32(base, kMatchSettings);
    const uint32_t map = CallVirtual(ctx, base, settings + kSettingsMap, 24) & 0xFF;
    choice.listed = std::find(std::begin(kNoRandomSpawnMaps), std::end(kNoRandomSpawnMaps), map) !=
                    std::end(kNoRandomSpawnMaps);
    std::vector<uint32_t> characters;
    for (uint32_t p = Load32(base, kParticipantList), n = 0; IsGuestPointer(p) && n < 64;
         p = Load32(base, p + 4), ++n)
    {
      const uint32_t character = Load32(base, p + kParticipantCharacter);
      if (p != self && IsGuestPointer(character))
      {
        characters.push_back(character);
      }
    }
    const uint32_t manager = Load32(base, kPadManager);
    const uint32_t list = IsGuestPointer(manager) ? Load32(base, manager + kPadSpawnList) : 0;
    const uint32_t count = IsGuestPointer(list) ? Load32(base, list) : 0;
    const uint32_t entries = IsGuestPointer(list) ? Load32(base, list + 4) : 0;
    std::vector<uint32_t> clear;
    std::vector<uint32_t> free;
    for (uint32_t i = 0; IsGuestPointer(entries) && i < count; ++i)
    {
      const uint32_t entry = entries + i * kPadEntrySize;
      const uint32_t node = Load32(base, entry);
      if (base[entry + 4] != 0 || !IsGuestPointer(node))
      {
        continue;
      }
      ++choice.total;
      const float to_base = NearestBase(base, node + kNodePosition);
      if (to_base < 0.0f || to_base < kBaseClear)
      {
        continue;
      }
      clear.push_back(node);
      const float at[3] = {LoadFloat(base, node + kNodePosition), LoadFloat(base, node + kNodePosition + 4),
                           LoadFloat(base, node + kNodePosition + 8)};
      const bool someone_near = std::any_of(characters.begin(), characters.end(), [&](uint32_t c) {
        return DistanceTo(base, c + kPosition, at) < kNobodyNear;
      });
      if (!someone_near)
      {
        free.push_back(node);
      }
    }
    choice.eligible = uint32_t(clear.size());
    if (choice.listed || choice.eligible < kMinRandomPads)
    {
      return choice;
    }
    static std::mt19937 rng{std::random_device{}()};
    const auto &pool = free.empty() ? clear : free;
    choice.node = pool[std::uniform_int_distribution<size_t>(0, pool.size() - 1)(rng)];
    return choice;
  }
} // namespace

