  constexpr uint32_t kProtTerminalCount = 112; // manager: terminals registered
  constexpr uint32_t kProtScores = 148;        // manager: team scores
  constexpr uint32_t kParticipantHandle = 952; // participant: its handle
  constexpr uint32_t kParticipantTeamVar = 120; // participant +80 -> team (replicated value)
  constexpr uint32_t kMatchProtection = 1016;  // match object: Protection manager

