// Distance (cm) from a character to the live Protection terminal (huge if none).
float LiveTerminalDistance(const uint8_t *base, uint32_t character)
{
  const uint32_t manager = g_protection;
  if (!IsGuestPointer(manager) || !IsGuestPointer(character))
  {
    return 1e9f;
  }
  const uint32_t live = Load32(base, manager + kProtLiveTerminal);
  const uint32_t terminal = live < 9 ? Load32(base, manager + live * 4) : 0;
  if (!IsGuestPointer(terminal))
  {
    return 1e9f;
  }
  float d2 = 0.0f;
  for (uint32_t i = 0; i < 3; ++i)
  {
    const float d = LoadFloat(base, terminal + kPosition + i * 4) - LoadFloat(base, character + kPosition + i * 4);
    d2 += d * d;
  }
  return std::sqrt(d2);
}

