// A bot hacker carrying the Data Thief puts its weapons away, as the
// holstered human hacker does (above): lower once, then after the animation
// take it out of the hand into the inventory; the hooks here refuse redraws
// while it carries (NoWeapons). Called every tick while it carries.
void PdzProtectionUnarmBot(PPCContext &ctx, uint8_t *base, uint32_t character, const char *label)
{
  const auto now = std::chrono::steady_clock::now();
  if (g_unarmed_bots.size() > 64)
  {
    g_unarmed_bots.clear();
  }
  g_unarmed_bots[character] = now;
  struct Lowering
  {
    uint32_t weapon = 0;
    std::chrono::steady_clock::time_point since;
  };
  static std::unordered_map<uint32_t, std::array<Lowering, 2>> lowering;
  if (lowering.size() > 64)
  {
    lowering.clear();
  }
  std::array<Lowering, 2> &hands = lowering[character];
  for (uint32_t hand = 0; hand < 2; ++hand)
  {
    const uint32_t weapon = Load32(base, character + kInventoryHands + hand * 4);
    if (!IsGuestPointer(weapon) || Load32(base, weapon + kWeaponType) == kItemDataThief)
    {
      hands[hand].weapon = 0;
      continue;
    }
    if (hands[hand].weapon != weapon)
    {
      CallVirtual(ctx, base, weapon, kWeaponLower);
      hands[hand] = {weapon, now};
      if (Log())
      {
        REXLOG_INFO("pdz_scenario: {} {:08X} puts away weapon {:08X} (type {}, hand {})", label, character, weapon,
                    Load32(base, weapon + kWeaponType), hand);
      }
    }
    else if (now - hands[hand].since >= kLowerTime)
    {
      rex::CallFrame frame(ctx);
      frame.ctx.r3.u64 = character;
      frame.ctx.r4.u64 = hand;
      frame.ctx.r5.u64 = 1;
      frame.ctx.r6.u64 = 0;
      sub_8254BB18(frame.ctx, base);
      hands[hand].weapon = 0;
      if (Log())
      {
        REXLOG_INFO("pdz_scenario: {} {:08X} weapon {:08X} out of hand {} (now {:08X})", label, character, weapon,
                    hand, Load32(base, character + kInventoryHands + hand * 4));
      }
    }
  }
}

