// --- Protection: a glow at the Data Thief ---
// The Data Thief lying at its base can't be seen: it has no world model
// (single player only ever lifts it at a terminal). Giving its setup record
// the first-person model (+0x70 := +0x6C) or a terminal's layer masks didn't
// help (logs 041-043), so those were dropped. It gets
// a particle effect instead: aid_xml_effect_hack2 (the spawn-room teleporter's
// hack effect, loaded in multiplayer), started at its position when it is
// placed (sub_8244DAC0) and stopped when it is gone (Protection tick).
// Effects: sub_82227C68 [822209A0](effects, name) -> effect; sub_82228240
// [82220F78](slot, effect, &position, &up, &forward, attach, r9, r10; caller
// stack +87 / +95 / +100) starts one (attach 0 = at a world position, as
// sub_82611C98 allows), sub_82228650 [82221388](slot) stops it.

REX_EXTERN(sub_82227C68);
REX_EXTERN(sub_82228240);
REX_EXTERN(sub_82228650);
REX_EXTERN(__imp__sub_8244C6C0);
REX_EXTERN(sub_8244DD70);
REX_EXTERN(sub_82202C78);

namespace
{
  constexpr uint32_t kEffects = 0x82D6C020;        // -> effects manager
  constexpr uint32_t kEffectHack2 = 0x820A3C14;    // "aid_xml_effect_hack2"
  constexpr uint32_t kVecUp = 0x82073C60;          // (0, 1, 0)
  constexpr uint32_t kVecForward = 0x82073C6C;     // (0, 0, 1)
  constexpr uint32_t kScratchSize = 0x10000;

  struct Glow
  {
    uint32_t thief = 0; // the Data Thief it marks
    uint32_t slot = 0;  // guest effect slot (8 bytes)
  };
  Glow g_glows[kTeams];
  uint32_t g_glow_manager = 0;
  uint32_t g_scratch = 0; // guest: a stack of our own, then a position vec

  bool GlowScratch()
  {
    if (!g_scratch)
    {
      g_scratch = REX_KERNEL_MEMORY()->SystemHeapAlloc(kScratchSize);
    }
    return g_scratch != 0;
  }
} // namespace

void PdzDataThiefGlowStart(PPCContext &ctx, uint8_t *base, uint32_t manager, uint32_t team)
{
  if (!ProtectionMatch(base) || team >= uint32_t(kTeams) || !GlowScratch())
  {
    return;
  }
  if (g_glow_manager != manager)
  {
    for (Glow &g : g_glows)
    {
      g = Glow{};
    }
    g_glow_manager = manager;
  }
  Glow &glow = g_glows[team];
  const uint32_t thief = Load32(base, manager + 132 + team * 4);
  if (!IsGuestPointer(thief) || glow.thief == thief)
  {
    return;
  }
  if (!glow.slot)
  {
    glow.slot = REX_KERNEL_MEMORY()->SystemHeapAlloc(8);
    if (!glow.slot)
    {
      return;
    }
    Store32(base, glow.slot, 0);
    Store32(base, glow.slot + 4, 0);
  }
  const uint32_t effects = Load32(base, kEffects);
  const uint32_t effect = IsGuestPointer(effects) ? uint32_t(Call(ctx, base, sub_82227C68, effects, kEffectHack2)) : 0;
  if (!effect)
  {
    if (Log())
    {
      REXLOG_INFO("pdz_scenario: Protection: no aid_xml_effect_hack2 effect; no glow");
    }
    return;
  }
  // Position: the Data Thief's, in the scratch block's last 16 bytes.
  const uint32_t position = g_scratch + kScratchSize - 16;
  for (uint32_t i = 0; i < 3; ++i)
  {
    Store32(base, position + i * 4, Load32(base, thief + kPosition + i * 4));
  }
  // Our own stack: frame top below the position; the stack arguments sit at
  // the caller's r1 + 87 / 95 / 100.
  const uint32_t sp = (g_scratch + kScratchSize - 0x200) & ~0xFu;
  Store32(base, sp, 0);
  base[sp + 87] = 0;
  base[sp + 95] = 1;
  Store32(base, sp + 100, 0);
  rex::CallFrame frame(ctx);
  frame.ctx.r1.u64 = sp;
  frame.ctx.r3.u64 = glow.slot;
  frame.ctx.r4.u64 = effect;
  frame.ctx.r5.u64 = position;
  frame.ctx.r6.u64 = kVecUp;
  frame.ctx.r7.u64 = kVecForward;
  frame.ctx.r8.u64 = 0;
  frame.ctx.r9.u64 = 0;
  frame.ctx.r10.u64 = 0;
  sub_82228240(frame.ctx, base);
  glow.thief = thief;
  if (Log())
  {
    REXLOG_INFO("pdz_scenario: Protection: team {} Data Thief glow started (effect {:08X}, slot {:08X}: {} emitter(s))",
                team, effect, glow.slot, Load32(base, glow.slot + 4));
  }
}

void PdzProtectionBotsTick(PPCContext &ctx, uint8_t *base, uint32_t manager);
