// sub_8244C6C0 [82440500](manager): the Protection tick; stops a glow whose
// Data Thief is gone (picked up, or a new one placed).
REX_HOOK_RAW(sub_8244C6C0)
{
  const uint32_t manager = ctx.r3.u32;
  uint32_t before[kTeams];
  for (uint32_t team = 0; team < uint32_t(kTeams); ++team)
  {
    before[team] = Load32(base, manager + 132 + team * 4);
  }
  __imp__sub_8244C6C0(ctx, base);
  if (Enabled())
  {
    // The tick clears the team's Data Thief slot when the hacker takes it
    // (8244CEE4), inline, without Rare's handler for it (sub_8244DD70: the
    // same clear plus GET_TO_TERMINAL to the hacker, never called). Call it.
    for (uint32_t team = 0; team < uint32_t(kTeams); ++team)
    {
      if (before[team] && !Load32(base, manager + 132 + team * 4))
      {
        Call(ctx, base, sub_8244DD70, manager, team);
      }
    }
    PdzProtectionBotsTick(ctx, base, manager);
  }
  if (manager != g_glow_manager)
  {
    return;
  }
  for (uint32_t team = 0; team < uint32_t(kTeams); ++team)
  {
    Glow &glow = g_glows[team];
    if (glow.thief && Load32(base, manager + 132 + team * 4) != glow.thief)
    {
      Call(ctx, base, sub_82228650, glow.slot);
      if (Log())
      {
        REXLOG_INFO("pdz_scenario: Protection: team {} Data Thief glow stopped", team);
      }
      glow.thief = 0;
    }
  }
}

// --- Protection: the announcer's hacker-down line ---
// Killing a hacker (sub_8244D868 [824416A8]) asks for
// MULTIPLAYER_HACKER_KILLED for the hacker's own team, but the speech bank's
// cue is hacker_down (multiplayer bank: protection, retrieve_datathief,
// get_to_terminal, terminal_hacked, enemy_hacker_killed, hacker_down), so
// the line never played. Cue names resolve through sub_82202C78 [821FAB60]
// (the name less "XACT_SOUNDBANK_" in the loaded banks' name table; -1 if
// none); the lookup by name (sub_82202D20) gets hacker_down instead.

namespace
{
  constexpr uint32_t kCueHackerKilled = 0x820B73A0; // XACT_SOUNDBANK_MULTIPLAYER_HACKER_KILLED
  constexpr const char *kCueHackerDown = "XACT_SOUNDBANK_MULTIPLAYER_HACKER_DOWN";
  uint32_t g_cue_hacker_down = 0;
} // namespace

uint32_t PdzProtectionCueName(uint8_t *base, uint32_t name)
{
  if (name != kCueHackerKilled || !Enabled())
  {
    return name;
  }
  if (!g_cue_hacker_down)
  {
    const size_t size = std::strlen(kCueHackerDown) + 1;
    g_cue_hacker_down = REX_KERNEL_MEMORY()->SystemHeapAlloc(uint32_t(size));
    if (!g_cue_hacker_down)
    {
      return name;
    }
    std::memcpy(base + g_cue_hacker_down, kCueHackerDown, size);
  }
  return g_cue_hacker_down;
}

// Logs whether the announcer's Protection cues resolve (match start).
void PdzProtectionCueCheck(PPCContext &ctx, uint8_t *base)
{
  const uint32_t down = PdzProtectionCueName(base, kCueHackerKilled);
  const int32_t killed = int32_t(Call(ctx, base, sub_82202C78, kCueHackerKilled));
  const int32_t fixed = down != kCueHackerKilled ? int32_t(Call(ctx, base, sub_82202C78, down)) : -1;
  const int32_t terminal = int32_t(Call(ctx, base, sub_82202C78, 0x820B73FCu));
  REXLOG_INFO("pdz_scenario: Protection cues: HACKER_KILLED {}, HACKER_DOWN {}, GET_TO_TERMINAL {}", killed, fixed,
              terminal);
}

