namespace
{
  // The chain of return addresses on the guest stack at a hooked call (back
  // chain at +0, saved LR at -8 of the caller's frame).
  std::string GuestCallers(const PPCContext &ctx, const uint8_t *base, int depth = 8)
  {
    std::string chain = fmt::format("{:08X}", uint32_t(ctx.lr));
    uint32_t sp = ctx.r1.u32;
    for (int i = 0; i < depth && IsGuestPointer(sp); ++i)
    {
      const uint32_t next = Load32(base, sp);
      // The outermost back chain is the stack's top, past its end (log 097
      // crashed reading it): stop at a 64 KB boundary or a long jump.
      if (!IsGuestPointer(next) || next <= sp || next - sp > 0x8000 || (next & 0xFFFF) == 0)
      {
        break;
      }
      chain += fmt::format(" < {:08X}", Load32(base, next - 8));
      sp = next;
    }
    return chain;
  }
} // namespace

