  // (the hitscan 8223FC00 rays with mask 1 and visitor 82090738). What a
  // human sees, the drum not taking damage, drops that firing pad.
  std::unordered_map<uint32_t, std::unordered_set<uint32_t>> g_bad_spots; // piece -> pads shots from which did not land
  std::unordered_map<uint32_t, uint32_t> g_property_open_pad; // prop -> the open pad found (melee fallback)
  std::unordered_map<uint32_t, float> g_property_spawn;  // prop -> health when first seen (its kind)
