  // home: groups 2 and 3 on goal 7 at one piece, group 1 roams.
  constexpr uint32_t kGoalGuard = 7;                   // CTF goal: guard the base (pad: kGoalGuardPadLookupReturn)
  constexpr uint32_t kGoalGuardApproach = 0x821C5C00;  // return address of goal 7's sub_8253A3E8 call
  constexpr uint32_t kBotGuardSpot = 14200;            // bot: the pad goal 7 picked (sub_8253A268)
  constexpr double kGuardStatus = 10.0;                // s between a guard's status lines
  struct SabotageDefence
  {
    uint32_t target = 0;                 // the piece the guards stay by
    double timer = kTeamReplan;          // s since the last re-plan (the first one at once)
    std::unordered_set<uint32_t> guards; // Rare's groups 2 and 3
    bool behind = false;                 // another team's score is higher
    uint32_t second = 0;                 // objective focus: group 3's piece (the next most valuable)
    std::unordered_set<uint32_t> second_guards; // objective focus: group 3
    float second_pos[3] = {};            // stage 2: where the second piece stood (re-guard after a loss)
    std::unordered_map<uint32_t, uint32_t> homes; // stage 2: responder -> the piece he holds near
    std::unordered_set<uint32_t> roamers;          // stage 2: the few left on Rare's roaming
    double roles_log = 0.0;                        // stage 2: s of the next roles line
  };
  struct SabotageGuard
  {
    uint32_t prop = 0;
    double clock = 0.0;
    double next_status = 5.0;
    std::chrono::steady_clock::time_point goal_set{};
    uint32_t spot = 0;          // our guard spot (a pad), 0 = none yet
    float prop_pos[3] = {};     // log 282: where his piece stood (his area)
    uint32_t far_logged = 0;    // log 282: the far piece last refused (logged once)
    float spot_closest = 0.0f;  // cm: the closest he got to it
    double spot_progress = 0.0; // s: when he last got 1 m closer, was there or fought
    double spot_reached = -1.0; // s: when he first got within kGuardArrived of it (-1: not yet)
    int picker_calls = 0;       // diagnostic: Rare's guard-spot picker calls since the last status line
    // Test (2026-10-25, log 271: guards re-picked a spot every second): the
    // spot is kept until the piece goes, the spot is blocked / out of reach,
    // he has stood there 8-12 s, or he fights; why_next is the reason the next
    // ask may give a new one (nullptr: keep it).
    double dwell = 0.0;         // s to stand at this spot (8-12, rolled on arrival)
    double piece_since = -100.0; // s (clock): when his piece last changed
    const char *why_next = nullptr;
  };
  std::unordered_map<uint32_t, SabotageDefence> g_defence_plans;  // defending team -> plan
  std::unordered_map<uint32_t, SabotageGuard> g_sabotage_guards;  // bot character -> its guard job

  // Stage 2: what a human defender gets: the announcer's "explosives set"
  // (no place) and "... destroyed" (the piece's radar blip goes: its
  // position). Queued here, acted on in the defending team's tick.
  constexpr int kEventDestroyed = 0;
  constexpr int kEventExplosivesSet = 1;
  struct DefenceEvent
  {
    int kind = 0;
    uint32_t piece = 0; // the piece (destroyed: its position below; explosives: the log's outcome only)
    uint32_t value = 0; // log 293: its Sabotage value (0 when unknown)
    float pos[3] = {};
    uint32_t actor = 0; // the planter (outcome only)
  };
  std::vector<DefenceEvent> g_defence_events;
  struct Reaction
  {
    int id = 0;
    int kind = 0;
    uint32_t true_piece = 0; // the piece really hit (outcome only: never steers anyone)
    uint32_t actor = 0;
    std::vector<std::pair<uint32_t, uint32_t>> sent; // responder, the piece he investigates
    std::vector<uint32_t> spots;                      // log 281: each one's destination (same order)
    std::unordered_set<uint32_t> arrived;
    double start = 0.0;
    double last_tick = 0.0; // log 290: DefClock at the last follow tick (the clock pauses in fights)
    double limit = 20.0; // s: the longest of the responders' times
    bool hit = false; // a responder hit an attacker meanwhile
    bool done = false;
  };
  std::vector<Reaction> g_reactions;
  struct Responding
  {
    int id = 0;
    uint32_t target = 0;
    double until = 0.0;
    uint32_t spot = 0; // log 281: his destination (a guard spot he can walk to), kept until he gets there
  };
  // Log 280 (Desert: 34 of 40 events found no free responder; the 6 sent
  // were 80+ m off with 20 s, 1 arrived): a responder reacts only to an
  // event within 40 m of him (a human defender doesn't cross the map for
  // one crate), and his time is the walk there (3.5 m/s) + 10 s, 15-60 s.
  constexpr float kReactRange = 4000.0f;
  double ReactSeconds(float cm)
  {
    return std::clamp(double(cm) / 350.0 + 10.0, 15.0, 60.0);
  }
  std::unordered_map<uint32_t, Responding> g_responding; // responder -> his reaction
  std::unordered_map<uint32_t, double> g_last_sent;       // responder -> when last sent (DefClock)
  int g_reaction_ids = 0;
  double DefClock()
  {
    static const auto start = std::chrono::steady_clock::now();
    return std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count();
  }

  void EndReaction(const uint8_t *base, Reaction &r, const char *outcome)
  {
    r.done = true;
    for (const auto &[bot, piece] : r.sent)
    {
      if (const auto it = g_responding.find(bot); it != g_responding.end() && it->second.id == r.id)
      {
        g_responding.erase(it);
      }
    }
    if (Log())
    {
      REXLOG_INFO("pdz_scenario: Sabotage bots: defence reaction #{} over after {:.1f} s: {} ({} of {} sent got there{})",
                  r.id, DefClock() - r.start, outcome, r.arrived.size(), r.sent.size(),
                  r.hit ? ", they hit an attacker" : "");
    }
    (void)base;
  }

  // Stage 2: an announcer event for the defenders (see DefenceEvent). A
  // destroyed piece also settles "explosives set" reactions on it.
  void PdzDefenceEvent(const uint8_t *base, int kind, uint32_t piece, uint32_t actor)
  {
    if (!REXCVAR_GET(pdz_sabotage_people_stage2) || !IsGuestPointer(piece))
    {
      return;
    }
    if (kind == kEventDestroyed)
    {
      for (Reaction &r : g_reactions)
      {
        if (!r.done && r.kind == kEventExplosivesSet && r.true_piece == piece)
        {
          EndReaction(base, r, r.arrived.empty() ? "too late (the piece blew)" : "arrived, but the piece blew");
        }
      }
    }
    if (g_defence_events.size() < 16)
    {
      DefenceEvent ev;
      ev.kind = kind;
      ev.piece = piece;
      ev.actor = actor;
      for (const SabotageProperty &p : g_property)
      {
        if (p.prop == piece)
        {
          ev.value = p.value;
        }
      }
      for (uint32_t i = 0; i < 3; ++i)
      {
        ev.pos[i] = LoadFloat(base, piece + kPosition + i * 4);
      }
      g_defence_events.push_back(ev);
    }
  }

  // Rare's activity says fight: 3 attack, 6 side-step, 7 dodge.
  bool GuardFighting(const uint8_t *base, uint32_t bot)
  {
    const uint32_t brain = objective_bots::BrainOf(base, bot);
    const uint32_t activity = brain ? Load32(base, brain + 0x38) : 0;
    return activity == 3 || activity == 6 || activity == 7;
  }
  // Our guard spots per piece (log 116: Rare's picker, sub_8253A268, takes any
  // pad within 10 m in a straight line, so for an upstairs piece it sent the
  // guards to the floor below and they stuck on the stairs). A spot a guard
  // couldn't reach is dropped; a piece with none left can't be guarded and
  // the team takes its next piece.
  struct GuardSpots
  {
    std::vector<uint32_t> pads;
    std::unordered_set<uint32_t> bad;
    int unwalkable = 0, walled = 0; // log 281: pads left out up front
    float floor = 0.0f; // the open pad's height
    uint32_t open_pad = 0; // the open pad they were found from
    // Log 239: some pads in the list are slots the game moves later (spot
    // 2F790F30 was listed 10 m from the power node, then read 72 m away; a
    // guard walked across the map after it). Where each spot was when found;
    // a spot that has moved more than 1 m since is dropped.
    std::unordered_map<uint32_t, std::array<float, 3>> at;
  };
  bool SpotMoved(const uint8_t *base, const GuardSpots &spots, uint32_t pad)
  {
    const auto it = spots.at.find(pad);
    if (it == spots.at.end())
    {
      return false; // a linked pad of the fallback: checked when picked
    }
    for (uint32_t i = 0; i < 3; ++i)
    {
      if (std::fabs(LoadFloat(base, pad + 16 + i * 4) - it->second[i]) > 100.0f)
      {
        return true;
      }
    }
    return false;
  }
  std::unordered_map<uint32_t, GuardSpots> g_guard_spots; // piece -> its spots
  std::unordered_set<uint32_t> g_unguardable;              // pieces no guard could reach
  constexpr float kGuardRadius = 1000.0f;  // cm, flat, from the piece (Rare's picker: 1000)
  constexpr float kGuardFloor = 200.0f;    // cm: a spot within this height of the open pad
  constexpr float kGuardSearch = 1200.0f;  // cm, flat: how far the link walk goes from the piece
  constexpr float kGuardArrived = 250.0f;  // cm from the spot
  constexpr double kGuardStuck = 8.0;      // s without 1 m of progress (not fighting; log 152: was 15)
  constexpr uint32_t kGuardSpotPick = 0x821C5BD8; // return address of goal 7's sub_8253A268 call
  uint32_t g_spot_vec = 0;                 // guest vec3 for the pad searches
