  bool PlaySquads()
  {
    return REXCVAR_GET(pdz_sabotage_play_squads) && REXCVAR_GET(pdz_sabotage_people_stage1);
  }
  struct Squad
  {
    int id = 0;                      // 1..3 (-1: the lone wolf's own pick)
    std::vector<uint32_t> members;   // bots, live or down
    std::vector<uint32_t> area;      // its area's pieces when picked
    bool node = false;               // the area holds the power node (the squad plants there)
    float weight = 0.0f, total = 0.0f; // its pick's weight and the sum it was drawn from
    std::string area_text;           // what the pick logged (for the round-over line)
    float centre[3] = {};            // live members' centre at the last plan
    float area_centre[3] = {};
    float via_side = 1.0f;           // the side of its first legs' via pads (stage 5's rule)
    int destroyed = 0, repicks = 0;
    bool node_support = false;       // log 093: no area left: it joins the node push (no more re-picks)
  };
  struct SquadPlan
  {
    uint64_t round_key = 0;          // mode << 32 | rounds played: one formation per round
    std::vector<Squad> squads;
    uint32_t lone = 0;               // this round's lone wolf (0: none)
    Squad lone_area;                 // his own pick (id -1)
    std::unordered_set<uint32_t> free; // attackers past three squads of four: the team plan's own picks
    int free_destroyed = 0;
  };
  std::unordered_map<uint32_t, SquadPlan> g_squads;                    // attacking team -> its squads this round
  std::unordered_map<uint32_t, std::pair<uint32_t, int>> g_squad_of;  // bot -> (team, squad id; -1 the lone wolf)
  // Enemies the attacking team's bots saw or heard (Rare's target +12652,
  // nearest known +14032), where and when (DefClock): an area with one seen
  // in the last 20 s weighs less.
  std::unordered_map<uint32_t, std::vector<std::pair<std::array<float, 3>, double>>> g_enemy_seen;

  Squad *SquadOf(uint32_t bot)
  {
    const auto s = g_squad_of.find(bot);
    const auto p = s != g_squad_of.end() ? g_squads.find(s->second.first) : g_squads.end();
    if (p == g_squads.end())
    {
      return nullptr;
    }
    if (s->second.second < 0)
    {
      return &p->second.lone_area;
    }
    for (Squad &q : p->second.squads)
    {
      if (q.id == s->second.second)
      {
        return &q;
      }
    }
    return nullptr;
  }

  void SquadRoundOver(const uint8_t *base); // below

  // A piece destroyed (Sabotage message 20, its destroyer): to his squad's tally.
  void SquadCredit(uint32_t actor)
  {
    if (Squad *q = PlaySquads() ? SquadOf(actor) : nullptr)
    {
      ++q->destroyed;
      return;
    }
    for (auto &[team, sp] : g_squads)
    {
      sp.free_destroyed += sp.free.count(actor) != 0;
    }
  }

  uint32_t g_last_defender = 0;  // stage 1: the one defender left alive (0: more, or none)
  constexpr float kPeopleWalk = 350.0f;   // cm/s: what bots really cover (log 272: 190 m took the whole round)
  constexpr float kOppDetour = 2000.0f;   // cm: a piece this near can take a detour
  constexpr float kOppEnemyNear = 1500.0f; // cm: no detour when a known enemy is this near the piece
  constexpr double kOppCap = 10.0;        // s
  constexpr double kOppCooldown = 8.0;    // s after a give-up (none after a kill: crates chain)

  bool Avoids(uint32_t bot, uint32_t prop)
  {
    const auto b = g_bot_avoid.find(bot);
    if (b == g_bot_avoid.end())
    {
      return false;
    }
    const auto it = b->second.find(prop);
    return it != b->second.end() && std::chrono::steady_clock::now() - it->second < std::chrono::seconds(60);
  }
  // Revives (2026-10-24: no respawn in Sabotage without a revive, and
