  // leave that bot alone while Rare's activity runs.
  constexpr uint32_t kActivityRevive = 11;
  constexpr uint32_t kBrainActivity = 0x38;
  constexpr uint32_t kItemReviveKit = 59;
  // Test (2026-10-25, log 270: trips from ~30 m, revivers dying on the way):
  // Rare's rule (821C6890): within 20 m, checked every 5 s, started only
  // while walking or looking with no enemy target.
  constexpr float kReviveRange = 2000.0f; // cm: a reviver this near the downed teammate
  struct Revive
  {
    uint32_t target = 0;
    std::chrono::steady_clock::time_point since{};
    std::chrono::steady_clock::time_point reissued{};
    int reissues = 0;
    float closest = 1e9f;                             // log 279: nearest he got (cm)
    std::chrono::steady_clock::time_point progress{}; // when he last got 0.5 m closer
  };
  std::unordered_map<uint32_t, Revive> g_revivers; // reviver bot -> the teammate he goes to revive
  // Log 235 (Mizar seemed to get stuck): a revive ran 25 s at 0.6 m
  // and the teammate never got up (beyond reviving), then was asked again.
  // A teammate a revive timed out on is left alone for 60 s (Desert
  // pathfinding: 20 s when no reviver can stand within Rare's revive reach).
  std::unordered_map<uint32_t, std::chrono::steady_clock::time_point> g_unrevivable; // downed teammate -> left alone until
  std::unordered_map<uint32_t, uint32_t> g_revive_stand; // Desert: reviver -> walkable pad within revive reach of the body

  // A bot's own name (its object name, "BOT-BERRI" -> "Berri"), for the log.
  std::string BotName(const uint8_t *base, uint32_t bot)
  {
    const uint32_t name = IsGuestPointer(bot) ? Load32(base, bot + 136) : 0; // kPropName (below)
    if (!IsGuestPointer(name))
    {
      // Log 313: the human (the player class) has no name there; his hits
      // and fights are named in the lines.
      return IsGuestPointer(bot) && Load32(base, bot) == 0x820C7DE0 ? "the human" : "?";
    }
    const char *text = reinterpret_cast<const char *>(base + name);
    std::string n(text, strnlen(text, 32));
    if (n.rfind("BOT-", 0) == 0)
    {
      n = n.substr(4);
    }
    for (size_t i = 1; i < n.size(); ++i)
    {
      n[i] = char(std::tolower(static_cast<unsigned char>(n[i])));
    }
    return n;
  }
  std::unordered_set<uint32_t> g_unplantable; // CP3: kit pieces a planter couldn't get to (shooting still goes on)
  std::unordered_set<uint32_t> g_down_logged; // attackers logged as down (kit holders: no respawn without a revive)
  // Log 313: every damage to a character in Sabotage, whoever the shooter
