  if ((NavFix() || g_desert) && !g_walls.empty() && IsGuestPointer(pad) && IsGuestPointer(character) &&
      SabotageBotsOn(base) && IsBot(base, character))
  {
    const float me[3] = {LoadFloat(base, character + kPosition), LoadFloat(base, character + kPosition + 4),
                         LoadFloat(base, character + kPosition + 8)};
    const float at[3] = {LoadFloat(base, pad + 16), LoadFloat(base, pad + 20) + 75.0f, LoadFloat(base, pad + 24)};
    if (WallBlocksWalk(me, at))
    {
      // Log 287: a substitute far from him made Rare route from a pad he
      // was not on (bots stuck inside the dump): only a pad within 3 m of
      // him on his side, else the given pad stays - and (log 291) he is
      // sent to walk to one within 15 m on his side, round the wall's end,
      // from his next frame (ProgressNudge), never left standing.
      const uint32_t other = OwnSidePad(ctx, base, character, pad, 0.0f, 300.0f);
      if (!other)
      {
        if (const uint32_t far = OwnSidePad(ctx, base, character, pad, 300.0f, 1500.0f))
        {
          g_walk_to_side[character] = far;
        }
      }
      ++g_round_counts.pad_snaps;
      static std::unordered_map<uint32_t, std::chrono::steady_clock::time_point> logged;
      const auto now = std::chrono::steady_clock::now();
      if (Log() && now - logged[character] > std::chrono::seconds(2))
      {
        logged[character] = now;
        REXLOG_INFO("pdz_scenario: Sabotage bots: current pad: {:08X} ({}) at ({:.0f}, {:.0f}, {:.0f}) was given pad {:08X} "
                    "at ({:.0f}, {:.0f}, {:.0f}) across a sandbag wall: {}",
                    character, BotName(base, character), me[0], me[1], me[2], pad, at[0], at[1] - 75.0f, at[2],
                    other ? fmt::format("pad {:08X} at ({:.0f}, {:.0f}, {:.0f}) on his side instead", other,
                                        LoadFloat(base, other + 16), LoadFloat(base, other + 20), LoadFloat(base, other + 24))
                          : std::string("no walkable pad on his side within 3 m: kept"));
      }
      if (other)
      {
        ctx.r4.u64 = other;
      }
    }
  }
