uint32_t PdzSabotageShopRoll(PPCContext &ctx, uint8_t *base, uint32_t roll)
{
  const uint32_t p = t_shop_participant;
  const uint32_t mode = REXCVAR_GET(pdz_sabotage_play_shop) && IsGuestPointer(p) ? SabotageMode(base) : 0;
  const int32_t count = int32_t(ctx.r28.u32);
  if (!mode || !SabotageBotsOn(base) || count <= 0 || count > 25)
  {
    return roll;
  }
  const uint32_t list = ctx.r1.u32 + 0x70;
  std::vector<uint32_t> types;
  std::string names;
  for (int32_t i = 0; i < count; ++i)
  {
    types.push_back(Load32(base, list + uint32_t(i) * 4));
    names += " " + GunTypeName(types.back());
  }
  const uint32_t character = Load32(base, p + kParticipantCharacter);
  const int team = ParticipantTeam(ctx, base, p);
  const bool defending = team >= 0 && uint32_t(team) == Load32(base, mode + kModeDefenders);
  const char *role = nullptr;
  std::vector<uint32_t> wants;
  if (defending)
  {
    role = "defender (Rare's random pick)";
  }
  else if (IsGuestPointer(character) && DemoKitOf(base, character))
  {
    role = "planter (keeps his money: a cheap sidearm)";
    wants = {2, 7, 15, 16, 11}; // P99, Falcon, Magsec, Plastigun, Magnum
  }
  else if (Unit(character * 2654435761u ^ g_round_salt ^ 0x5A0Bu) < 1.0f / 3.0f)
  {
    role = "demolition (launchers for hard pieces and clusters)";
    wants = {23, 22, 13, 9}; // rocket launcher, Devastator, SuperDragon, M16 (the last two: grenade secondaries)
  }
  else
  {
    role = "crate breaker (rapid fire, shotgun)";
    wants = {13, 10, 1, 20, 12, 9, 3, 19, 18, 5, 17}; // SuperDragon, M60, AK47, RCP120, Shotgun, M16, MP5, ...
  }
  int32_t pick = -1;
  for (const uint32_t want : wants)
  {
    for (int32_t i = 0; pick < 0 && i < count; ++i)
    {
      pick = types[size_t(i)] == want ? i : -1;
    }
    if (pick >= 0)
    {
      break;
    }
  }
  if (Log())
  {
    const int32_t rare = int32_t(roll % uint32_t(count));
    REXLOG_INFO("pdz_scenario: Sabotage shop (stage 4): {} ({}, team {} {}), role {}: {} (Rare's roll: {}); the shop's "
                "list:{}",
                BotName(base, character), p, team, defending ? "defending" : "attacking", role,
                pick >= 0 ? fmt::format("buys {} (index {} of {})", GunTypeName(types[size_t(pick)]), pick, count)
                          : std::string(wants.empty() ? "Rare's roll stands" : "none of his picks in the list: Rare's roll stands"),
                GunTypeName(types[size_t(rare)]), names);
  }
  return pick >= 0 ? uint32_t(pick) : roll;
}

