// Who lowers a planting bot's kit (logs 193-195: the switcher's update then
// holsters it, 824F9128, with no slot-0 select refused)? The kit's Lower
// (8257BA68, state 4) and its forced lowered state (8257B928, state 2) are
// logged with the caller chain when the kit belongs to a bot mid-plant.
void KitLowerDiag(PPCContext &ctx, uint8_t *base, uint32_t kit, const char *what)
{
  if (!Log() || !SabotageBotsOn(base))
  {
    return;
  }
  for (const auto &[bot, job] : g_sabotage_attackers)
  {
    if (job.kit != kit || !job.planting)
    {
      continue;
    }
    static int lines = 0;
    if (lines >= 40)
    {
      return;
    }
    ++lines;
    const uint32_t back1 = Load32(base, ctx.r1.u32);
    const uint32_t lr1 = IsGuestPointer(back1) ? Load32(base, back1 - 8) : 0;
    const uint32_t back2 = IsGuestPointer(back1) ? Load32(base, back1) : 0;
    const uint32_t lr2 = IsGuestPointer(back2) ? Load32(base, back2 - 8) : 0;
    REXLOG_INFO("pdz_scenario: Sabotage bots: attacker {:08X}'s demo kit {:08X} {} while he plants ({:.1f} of {:.1f} s; kit "
                "state {}); called from {:08X} < {:08X} < {:08X}",
                bot, kit, what, job.plant_time, job.plant_need, int32_t(Load32(base, kit + 0x54c)), uint32_t(ctx.lr), lr1, lr2);
    return;
  }
}

// Log 286 (weapon swapping on screen while a bot planted with enemies
// targeted): Rare's combat lowers the kit for the gun and our draw brings it
// back, a tug-of-war. Stage 1: a live planter's kit refuses the lower while
// he plants (the plant's lock already refuses the select, 824F9EB0).
bool PlantingKit(PPCContext &ctx, uint8_t *base, uint32_t kit)
{
  if (!PeopleStage1() || !SabotageBotsOn(base))
  {
    return false;
  }
  for (const auto &[bot, job] : g_sabotage_attackers)
  {
    if (job.kit == kit && job.planting && !objective_bots::CharacterDown(ctx, base, bot))
    {
      ++g_round_counts.lowers_refused;
      return true;
    }
  }
  return false;
}

// pdz_protection_hack_under_fire (2026-10-27; log 052: every hack under
// fire was cancelled within a second of the first hits). From the TU3 code
// (read-only): the cancel is the Data Thief's pending lower byte (+0x550,
// the gadget's +1360) read by its update (8257AC44 calls the gadget's Lower,
// vtable +496, when it is set). That byte is set by the gadget's own Lower
// (8257BA68, the gadget vtable 820C4100 +496) when it is called while the
// gadget is busy (state not 1 / 5 / 6, e.g. the minigame). The four setters
// the log 052 build watched (8255BE40 / 8255BE60 / 822481C0 / 82244BE8) are
// referenced nowhere in TU3 (no call, branch, vtable entry or address
// constant): dead code, so they never fire. The Lower's callers are virtual
// (slot +496): the weapon switcher (824F8F80 at 824F908C, its lower-request
// bytes; 824F83B8; 824F7360; 824F9CF8) and others; which one the damage
// handler (82546BC8) reaches goes through its character vtable calls and a
// recorded hit reaction (825BAEC8, char +0x3C0) read later by the animation
// code, so it is left to the play test: each refused call logs its caller
// chain. The fix: for a Protection hacker's Data Thief, while he is alive and
// hacking (its target hackable +1312 set, or the live terminal's use action
// marked him within 0.5 s), the Lower and the forced lowered state
// (8257B928) are refused. Death (he is down) or leaving the terminal (mark
// stale, target cleared) lets them through, so a hack still ends there.
namespace
{
  // Last time each character took damage in a Protection match (both damage
  // routes: the player class 825AAF50, minigame_log.cpp; the shared 82546BC8).
  std::unordered_map<uint32_t, std::chrono::steady_clock::time_point> g_protection_hit;
} // namespace

void PdzCharacterHit(uint32_t victim)
{
  if (IsGuestPointer(g_protection))
  {
    if (g_protection_hit.size() > 64)
    {
      g_protection_hit.clear();
    }
    g_protection_hit[victim] = std::chrono::steady_clock::now();
  }
}

bool HackUnderFire(PPCContext &ctx, uint8_t *base, uint32_t gadget, const char *what)
{
  if (!Enabled() || !ProtectionMatch(base) || !IsGuestPointer(gadget) ||
      Load32(base, gadget + kWeaponType) != kItemDataThief)
  {
    return false;
  }
  const uint32_t owner = Load32(base, gadget + 92); // gadget: its owner (character), as the demo kit's
  const uint32_t target = Load32(base, gadget + kGadgetTargetHackable);
  const auto at = g_at_terminal.find(owner);
  const bool marked = at != g_at_terminal.end() && std::chrono::steady_clock::now() - at->second < kAtTerminalStale;
  const bool alive = IsGuestPointer(owner) && !objective_bots::CharacterDown(ctx, base, owner);
  const bool hacking = alive && (IsGuestPointer(target) || marked);
  const auto hit = g_protection_hit.find(owner);
  const bool under_fire = hit != g_protection_hit.end() && std::chrono::steady_clock::now() - hit->second < std::chrono::seconds(2);
  // Only under fire (hit in the last 2 s): a lower at the hack's own end, or
  // any other, stays Rare's.
  const bool refuse = hacking && under_fire && REXCVAR_GET(pdz_protection_hack_under_fire);
  static int lines = 0;
  static uint32_t match = 0;
  if (match != g_protection)
  {
    match = g_protection;
    lines = 0;
  }
  if (Log() && lines < 60)
  {
    ++lines;
    const uint32_t back1 = Load32(base, ctx.r1.u32);
    const uint32_t lr1 = IsGuestPointer(back1) ? Load32(base, back1 - 8) : 0;
    const uint32_t back2 = IsGuestPointer(back1) ? Load32(base, back1) : 0;
    const uint32_t lr2 = IsGuestPointer(back2) ? Load32(base, back2 - 8) : 0;
    REXLOG_INFO("pdz_scenario: Protection hack under fire: Data Thief {:08X} of {:08X} {} (state {}, target hackable "
                "{:08X}, terminal mark {}, {}, {}); called from {:08X} < {:08X} < {:08X}: {}",
                gadget, owner, what, int32_t(Load32(base, gadget + 0x54c)), target, marked ? "fresh" : "stale",
                alive ? "alive" : "down", under_fire ? "hit in the last 2 s" : "not hit lately", uint32_t(ctx.lr), lr1, lr2,
                refuse       ? "REFUSED (fix: the hack goes on)"
                : !hacking   ? "let through (not hacking: dead or away from the terminal)"
                : !under_fire ? "let through (not under fire)"
                              : "let through (pdz_protection_hack_under_fire off)");
  }
  return refuse;
}

REX_EXTERN(__imp__sub_8257B928);
REX_HOOK_RAW(sub_8257B928)
{
  KitLowerDiag(ctx, base, ctx.r3.u32, "forced to its lowered state (8257B928)");
  if (PlantingKit(ctx, base, ctx.r3.u32) || HackUnderFire(ctx, base, ctx.r3.u32, "forced to its lowered state (8257B928)"))
  {
    return;
  }
  __imp__sub_8257B928(ctx, base);
}

