// A bot was hit (from the shared character damage routine sub_82546BC8
// [82537548], hooked below; the player-class handler sub_825AAF50 never saw
// bot hits, log 071): logged with its job, to catch a bot that seems not to
// take damage (log 070: one of the enemy bots seemed invincible).
void PdzProtectionBotDamaged(PPCContext &ctx, uint8_t *base, uint32_t victim, uint32_t attacker, double damage)
{
  if (!BotsEnabled(base) || !Log() || !IsBot(base, victim))
  {
    return;
  }
  static std::unordered_map<uint32_t, std::pair<uint32_t, double>> hits; // per bot character: count, total
  if (hits.size() > 64)
  {
    hits.clear();
  }
  auto &h = hits[victim];
  ++h.first;
  h.second += damage;
  std::string job = "helper";
  for (uint32_t team = 0; team < uint32_t(kTeams); ++team)
  {
    const BotHacker &b = g_bot_hackers[team];
    if (b.character == victim)
    {
      job = fmt::format("team {} hacker, {}{}", team, b.carrying ? "carrying" : "fetching",
                        b.hack.Running() ? ", hacking" : "");
    }
  }
  const auto role = g_bot_roles.find(victim);
  REXLOG_INFO("pdz_scenario: Protection bots: bot {:08X} ({}{}) hit for {:.1f} by {:08X}; {} hits, {:.1f} damage "
              "since it spawned",
              victim, job, role != g_bot_roles.end() ? fmt::format(", role {}", objective_bots::RoleName(role->second)) : "",
              damage, attacker, h.first, h.second);
  (void)ctx;
}

