// sub_82546BC8 [82537548](character, attacker, f1 damage, ...): a character
// takes damage (vtable slot of many character classes).
namespace
{
  // Damage in Sabotage (pdz_scenario_log; log 274: bots shot each
  // other at the pieces): attacker, victim, teams, gun, damage, what the
  // attacker aimed at. Friendly hits are all logged (with no damage too: a
  // teammate's body stopped the shot); enemy hits are counted, logged at
  // most 5 a second.
  uint32_t CharacterOf(const uint8_t *base, uint32_t who)
  {
    if (!IsGuestPointer(who))
    {
      return 0;
    }
    const uint32_t vt = Load32(base, who);
    if (vt == kBotVtable || vt == 0x820C7DE0u)
    {
      return who;
    }
    const uint32_t owner = Load32(base, who + 92); // a weapon / kit: its owner
    return IsGuestPointer(owner) && (Load32(base, owner) == kBotVtable || Load32(base, owner) == 0x820C7DE0u) ? owner : 0;
  }

  void SabotageDamageLog(PPCContext &ctx, uint8_t *base, uint32_t victim, uint32_t source, double damage)
  {
    if (!Log() || !(SabotageBotsOn(base) || PdzDuelMatch(base))) // Duel: log 118, bots fought and never died
    {
      return;
    }
    const uint32_t attacker = CharacterOf(base, source);
    const uint32_t vp = IsGuestPointer(victim) ? CallVirtual(ctx, base, victim, kCharacterParticipant) : 0;
    const uint32_t ap = attacker ? CallVirtual(ctx, base, attacker, kCharacterParticipant) : 0;
    const int vteam = IsGuestPointer(vp) ? ParticipantTeam(ctx, base, vp) : -1;
    const int ateam = IsGuestPointer(ap) ? ParticipantTeam(ctx, base, ap) : -1;
    // Duel free for all: everyone is on team 0, but two different characters are enemies (log 273 called every
    // Haybot / Countbatula hit FRIENDLY).
    const bool friendly =
        attacker && attacker != victim && vteam >= 0 && vteam == ateam && !PdzDuelFreeForAll(base);
    ++g_round_counts.hits;
    std::string aimed = "-";
    if (const auto a = g_sabotage_attackers.find(attacker); a != g_sabotage_attackers.end() && a->second.prop &&
                                                            (a->second.shooting || a->second.stance))
    {
      aimed = fmt::format("property {:08X}", a->second.prop);
      if (friendly)
      {
        ++g_round_counts.friendly_property;
      }
    }
    else if (attacker && Load32(base, attacker) == 0x820C7DE0)
    {
      aimed = "his own aim"; // log 313: the human; +12652 is a bot field ("player 3F800000")
    }
    else if (attacker)
    {
      const uint32_t target = Load32(base, attacker + 12652);
      aimed = IsGuestPointer(target) ? fmt::format("player {:08X}", target) : std::string("nothing");
    }
    if (friendly)
    {
      ++g_round_counts.friendly;
      g_round_counts.friendly_no_damage += damage <= 0.0;
    }
    else if (const auto r = g_responding.find(attacker); r != g_responding.end() && damage > 0.0)
    {
      for (Reaction &re : g_reactions)
      {
        re.hit |= re.id == r->second.id;
      }
    }
    static auto window = std::chrono::steady_clock::now();
    static int lines = 0;
    const auto now = std::chrono::steady_clock::now();
    if (now - window > std::chrono::seconds(1))
    {
      window = now;
      lines = 0;
    }
    if (!friendly && ++lines > 5)
    {
      return;
    }
    const uint32_t gun = attacker ? Load32(base, attacker + 4080) : 0;
    REXLOG_INFO("pdz_scenario: Sabotage damage: {}{:08X} ({}, team {}) hit {:08X} ({}, team {}) for {:.1f} with {}, aiming "
                "at {}{}",
                friendly ? "FRIENDLY: " : "", attacker ? attacker : source, attacker ? BotName(base, attacker) : "?", ateam,
                victim, BotName(base, victim), vteam, damage, IsWeapon(base, gun) ? GunText(base, gun) : std::string("-"),
                aimed, friendly && damage <= 0.0 ? " (no damage: his body stopped the shot)" : "");
  }
} // namespace

REX_HOOK_RAW(sub_82546BC8)
{
  SabotageDamageLog(ctx, base, ctx.r3.u32, ctx.r4.u32, ctx.f1.f64);
  if (ctx.f1.f64 > 0.0)
  {
    if (SabotageBotsOn(base) && IsGuestPointer(ctx.r3.u32))
    {
      // Log 313: every hit, whoever the shooter (the human too): snap shots,
      // plant fights and revives read it (HitAgo, g_hit_by).
      if (g_hit_by.size() > 128)
      {
        g_hit_by.clear();
      }
      // Enemy hits only (and hits with no shooter, a blast): a teammate's
      // stray shot never makes a planter fight him or stops a revive.
      const uint32_t shooter = CharacterOf(base, ctx.r4.u32);
      bool friendly = false;
      if (IsGuestPointer(shooter) && shooter != ctx.r3.u32)
      {
        const uint32_t vp = CallVirtual(ctx, base, ctx.r3.u32, kCharacterParticipant);
        const uint32_t sp = CallVirtual(ctx, base, shooter, kCharacterParticipant);
        friendly = IsGuestPointer(vp) && IsGuestPointer(sp) && ParticipantTeam(ctx, base, vp) == ParticipantTeam(ctx, base, sp);
      }
      if (!friendly)
      {
        g_hit_by[ctx.r3.u32] = {shooter != ctx.r3.u32 ? shooter : 0u, std::chrono::steady_clock::now()};
      }
    }
    PdzCharacterHit(ctx.r3.u32); // Protection: hack under fire
    if (const auto a = g_sabotage_attackers.find(ctx.r3.u32); a != g_sabotage_attackers.end())
    {
      a->second.hit = true; // a stance re-evaluates on damage
      a->second.last_hit = a->second.clock;
    }
    PdzProtectionBotDamaged(ctx, base, ctx.r3.u32, ctx.r4.u32, ctx.f1.f64);
  }
  __imp__sub_82546BC8(ctx, base);
}

namespace
{
  // Log 109: a bot hacker carrying the Data Thief stood still for 40 s with
  // nothing logged about him (the helpers' check, StillCheck, skips hackers).
  // Here: once per stand of 4 s (1 m) while fetching or walking (not while the
  // hack holds him), his goal, goal pad (+14200, set by Rare's planner),
  // brain state and refused draws; and Rare's re-plan, once per stand.
  void HackerStillCheck(PPCContext &ctx, uint8_t *base, uint32_t team, uint32_t bot, bool carrying, uint32_t target,
                        bool hacking)
  {
    struct Still
    {
      float pos[3] = {};
      std::chrono::steady_clock::time_point since{};
      bool done = false;
    };
    static std::unordered_map<uint32_t, Still> still;
    if (still.size() > 16)
    {
      still.clear();
    }
    Still &st = still[bot];
    const auto now = std::chrono::steady_clock::now();
    float pos[3];
    float d2 = 0.0f;
    for (uint32_t i = 0; i < 3; ++i)
    {
      pos[i] = LoadFloat(base, bot + kPosition + i * 4);
      d2 += (pos[i] - st.pos[i]) * (pos[i] - st.pos[i]);
    }
    if (hacking || d2 > 100.0f * 100.0f || st.since == std::chrono::steady_clock::time_point{})
    {
      st = Still{{pos[0], pos[1], pos[2]}, now, false};
      g_draws_refused.erase(bot);
      return;
    }
    if (st.done || now - st.since < std::chrono::seconds(4))
    {
      return;
    }
    st.done = true;
    const uint32_t brain = objective_bots::BrainOf(base, bot);
    if (Log())
    {
      const uint32_t pad = Load32(base, bot + 14200); // goal pad (Rare's planner: goal 4 / 7)
      const auto refused = g_draws_refused.find(bot);
      REXLOG_INFO("pdz_scenario: Protection bots: team {} bot hacker {:08X} ({}) hasn't moved for 4 s: goal {}, goal pad "
                  "{:08X}, {:.1f} m from {} {:08X}; brain {:08X} activity {} phase {}, route task {:08X}, vehicle roll {}; "
                  "hands {:08X} {:08X}; {} draw(s) refused; Rare's re-plan asked",
                  team, bot, carrying ? "carrying" : "fetching", int32_t(Load32(base, bot + kBotGoal)), pad,
                  IsGuestPointer(target) ? Distance(base, bot, target) / 100.0f : -1.0f,
                  carrying ? "the terminal" : "the Data Thief", target, brain,
                  brain ? int32_t(Load32(base, brain + 56)) : -1, brain ? int32_t(Load32(base, brain + 292)) : -1,
                  brain ? Load32(base, brain + 92) : 0, brain ? int(base[brain + 257]) : -1,
                  Load32(base, bot + kInventoryHands), Load32(base, bot + kInventoryHands + 4),
                  refused == g_draws_refused.end() ? 0u : refused->second);
    }
    g_draws_refused.erase(bot);
    if (brain)
    {
      OurReplan(ctx, base, brain, "the bot hacker stood still 4 s");
    }
  }

  // Rare's guard goal 7 at the live terminal (the goal-7 pad lookup above
  // answers the pad; Rare's spot picker 8253A268 then patrols within 10 m).
  void PatrolGoal(PPCContext &ctx, uint8_t *base, uint32_t bot, uint32_t team, bool terminal_moved)
  {
    objective_bots::Role &last = g_bot_roles[bot];
    GoalSent &sent = g_goal_sent[bot];
    const auto now = std::chrono::steady_clock::now();
    const bool changed = sent.goal != kGoalGuard || sent.target != 0;
    if (changed || now - sent.at > std::chrono::seconds(5))
    {
      Store32(base, bot + kBotGoalTeam, team);
      objective_bots::SetGoal(ctx, base, bot, kGoalGuard, 0);
      sent = GoalSent{kGoalGuard, 0, now};
    }
    if (terminal_moved && !changed)
    {
      if (const uint32_t brain = objective_bots::BrainOf(base, bot))
      {
        OurReplan(ctx, base, brain, "the live terminal moved"); // Rare's re-plan: the new terminal
      }
    }
    if (Log() && (last != objective_bots::Role::Guard || changed))
    {
      REXLOG_INFO("pdz_scenario: Protection bots: bot {:08X} patrols the live terminal (goal 7)", bot);
    }
    last = objective_bots::Role::Guard;
  }

  // pdz_protection_fair_hunt (2026-10-27: hunters must not cheat).
  // Rare's goal 3 (attack the carrier) needs no perception: the planner's
  // case for it (821C5884, jump table 8208DF48 entry 3) hands the goal's
  // target character straight to the chooser, 821C4308(brain, 3, target,
  // forced 1), and when a fight loses its target (8253A7C8) 821C6C10 ends it
  // for every goal but 3. So a hunter on goal 3 walks to the enemy hacker
  // wherever he is. What a bot really knows of enemies is its perception
  // list (char +0x354, the slot Rare's nearest-enemy pick 82539388 walks with
  // 8218B498: an iterator {82090E08, slot, 0, 1}; each entry a character it
  // saw or heard; Rare fills it, our goals never do). Fair: a hunter hunts
  // the hacker only while the hacker is in his own list, and 5 s after;
  // otherwise he patrols the live terminal (where any hacker must go) on
  // goal 7. Looked at twice a second per hunter; every switch is logged.
  uint32_t g_perceive_iter = 0; // guest scratch: the iterator (16 bytes) and its out word (16)

  bool Perceives(PPCContext &ctx, uint8_t *base, uint32_t bot, uint32_t target)
  {
    const uint32_t slot = Load32(base, bot + 0x354);
    if (!IsGuestPointer(slot) || !IsGuestPointer(target))
    {
      return false;
    }
    if (!g_perceive_iter && !(g_perceive_iter = REX_KERNEL_MEMORY()->SystemHeapAlloc(32)))
    {
      return false;
    }
    Store32(base, g_perceive_iter, 0x82090E08);
    Store32(base, g_perceive_iter + 4, slot);
    Store32(base, g_perceive_iter + 8, 0);
    Store32(base, g_perceive_iter + 12, 1);
    for (int n = 0; n < 64; ++n)
    {
      rex::CallFrame frame(ctx);
      frame.ctx.r1.u64 = (ctx.r1.u32 - 0x800) & ~0xFu;
      frame.ctx.r3.u64 = g_perceive_iter;
      frame.ctx.r4.u64 = g_perceive_iter + 16;
      sub_8218B498(frame.ctx, base);
      const uint32_t who = frame.ctx.r3.u32;
      if (!IsGuestPointer(who))
      {
        return false;
      }
      if (who == target)
      {
        return true;
      }
    }
    return false;
  }

  struct FairHunt
  {
    std::chrono::steady_clock::time_point seen{};  // last time he perceived the hacker
    std::chrono::steady_clock::time_point check{}; // next perception look
    uint32_t hacker = 0;
    int mode = 0;                                   // 1 hunting, 2 patrolling (logged on change)
  };
  std::unordered_map<uint32_t, FairHunt> g_fair_hunt; // hunter -> his state

  // True: hunt now (he perceives the hacker or did within 5 s).
  bool FairHuntNow(PPCContext &ctx, uint8_t *base, uint32_t bot, uint32_t hacker)
  {
    FairHunt &h = g_fair_hunt[bot];
    const auto now = std::chrono::steady_clock::now();
    if (h.hacker != hacker)
    {
      h = FairHunt{};
      h.hacker = hacker;
    }
    if (now >= h.check)
    {
      h.check = now + std::chrono::milliseconds(500);
      if (Perceives(ctx, base, bot, hacker))
      {
        h.seen = now;
      }
    }
    return h.seen != std::chrono::steady_clock::time_point{} && now - h.seen < std::chrono::seconds(5);
  }

  void FairHuntLog(const uint8_t *base, uint32_t bot, uint32_t hacker, int mode, uint32_t group)
  {
    FairHunt &h = g_fair_hunt[bot];
    if (h.mode == mode || !Log())
    {
      h.mode = mode;
      return;
    }
    h.mode = mode;
    const double ago = h.seen == std::chrono::steady_clock::time_point{}
                           ? -1.0
                           : std::chrono::duration<double>(std::chrono::steady_clock::now() - h.seen).count();
    REXLOG_INFO("pdz_scenario: Protection fair hunt: bot {:08X} (group {}) {} enemy hacker {:08X}{} ({:.1f} m)", bot, group,
                mode == 1 ? "hunts (goal 3)" : "patrols the live terminal (goal 7) instead of hunting", hacker,
                mode == 1 ? " (he perceives him)"
                : ago < 0.0 ? ", never perceived"
                            : fmt::format(", last perceived {:.1f} s ago", ago),
                Distance(base, bot, hacker) / 100.0f);
  }

  // pdz_protection_objective_focus (2026-10-25: the hacker is the
  // carrier): Rare's CTF groups (8214ACC0: group 2 = n / 6 + 1, none below
  // 2; group 3 = n / 7 + 1, none below 4; group 1 the rest) over each team's
  // helper bots in member order. Group 1 escorts its hacker (goal 8), or
  // without one hunts the enemy hacker (goal 3), else patrols; group 2
  // patrols the live terminal (goal 7); group 3 hunts the enemy hacker, or
  // roams on Rare's goal 0 when there is none.
  void FocusRoles(PPCContext &ctx, uint8_t *base, uint32_t manager, const uint32_t (&hackers)[kTeams],
                  uint32_t terminal)
  {
    (void)manager;
    const bool terminal_moved = terminal != g_patrol_terminal;
    g_patrol_terminal = terminal;
    g_terminal_patrol.clear();
    for (uint32_t team = 0; team < uint32_t(kTeams); ++team)
    {
      uint32_t enemy = 0;
      for (uint32_t other = 0; other < uint32_t(kTeams) && !enemy; ++other)
      {
        if (other != team && IsGuestPointer(hackers[other]) && !objective_bots::CharacterDown(ctx, base, hackers[other]))
        {
          enemy = hackers[other];
        }
      }
      const bool own = IsGuestPointer(hackers[team]) && !objective_bots::CharacterDown(ctx, base, hackers[team]);
      std::vector<uint32_t> helpers;
      for (uint32_t p : TeamMembers(ctx, base, team))
      {
        const uint32_t bot = Load32(base, p + kParticipantCharacter);
        if (IsBot(base, bot) && bot != hackers[team])
        {
          helpers.push_back(bot);
        }
      }
      const size_t n = helpers.size();
      const size_t group2 = n < 2 ? 0 : n / 6 + 1;
      const size_t group3 = n < 4 ? 0 : n / 7 + 1;
      const size_t group1 = n - std::min(n, group2 + group3);
      for (size_t i = 0; i < n; ++i)
      {
        const uint32_t bot = helpers[i];
        const int group = i < group1 ? 1 : i < group1 + group2 ? 2 : 3;
        if (group == 1 && own)
        {
          StillCheck(ctx, base, bot, objective_bots::Role::Escort);
          SetRole(ctx, base, bot, objective_bots::Role::Escort, objective_bots::kGoalEscort, hackers[team]);
        }
        else if ((group == 1 || group == 3) && enemy && REXCVAR_GET(pdz_protection_fair_hunt) &&
                 !FairHuntNow(ctx, base, bot, enemy))
        {
          // Fair hunt: he doesn't perceive the hacker: the live terminal.
          if (IsGuestPointer(terminal))
          {
            StillCheck(ctx, base, bot, objective_bots::Role::Guard);
            g_terminal_patrol.insert(bot);
            PatrolGoal(ctx, base, bot, team, terminal_moved);
          }
          else
          {
            SetRole(ctx, base, bot, objective_bots::Role::Guard, objective_bots::kGoalRoam, 0);
          }
          FairHuntLog(base, bot, enemy, 2, uint32_t(group));
        }
        else if ((group == 1 || group == 3) && enemy)
        {
          StillCheck(ctx, base, bot, objective_bots::Role::Hunt);
          SetRole(ctx, base, bot, objective_bots::Role::Hunt, objective_bots::kGoalAttackCarrier, enemy);
          if (REXCVAR_GET(pdz_protection_fair_hunt))
          {
            FairHuntLog(base, bot, enemy, 1, uint32_t(group));
          }
        }
        else if (group != 3 && IsGuestPointer(terminal))
        {
          StillCheck(ctx, base, bot, objective_bots::Role::Guard);
          g_terminal_patrol.insert(bot);
          PatrolGoal(ctx, base, bot, team, terminal_moved);
        }
        else
        {
          SetRole(ctx, base, bot, objective_bots::Role::Guard, objective_bots::kGoalRoam, 0);
        }
      }
    }
  }
} // namespace

void PdzProtectionBotsTick(PPCContext &ctx, uint8_t *base, uint32_t manager)
{
  if (!BotsEnabled(base))
  {
    return;
  }
  const auto now = std::chrono::steady_clock::now();
  if (g_bots_manager != manager)
  {
    for (BotHacker &h : g_bot_hackers)
    {
      h = BotHacker{};
    }
    g_hacker_target.clear();
    g_goal_set.clear();
    g_bot_roles.clear();
    g_goal_sent.clear();
    g_fair_hunt.clear();
    g_bots_manager = manager;
    g_bots_last = now;
  }
  const double dt = std::min(0.25, std::chrono::duration<double>(now - g_bots_last).count());
  g_bots_last = now;
  const uint32_t terminal = LiveTerminal(base, manager);

  uint32_t hackers[kTeams] = {};
  for (uint32_t team = 0; team < uint32_t(kTeams); ++team)
  {
    hackers[team] = Hacker(ctx, base, manager, team).second;
  }

  for (uint32_t team = 0; team < uint32_t(kTeams); ++team)
  {
    const auto [participant, character] = Hacker(ctx, base, manager, team);
    BotHacker &h = g_bot_hackers[team];
    if (participant != h.participant || character != h.character)
    {
      // A new hacker, or the bot respawned (a new character): start over.
      if (Log() && h.carrying)
      {
        REXLOG_INFO("pdz_scenario: Protection bots: team {} hacker gone while carrying; hack {}", team,
                    h.hack.Running() ? "interrupted (died)" : "not started");
      }
      g_hacker_target.erase(h.character);
      h = BotHacker{};
      h.participant = participant;
      h.character = character;
    }
    if (!IsBot(base, character))
    {
      continue; // humans: Rare's tick
    }
    if (objective_bots::CharacterDown(ctx, base, character))
    {
      // Down: no fetch, no hack progress (Rare handles the death).
      if (h.hack.Running())
      {
        h.hack.Clear();
        if (Log())
        {
          REXLOG_INFO("pdz_scenario: Protection bots: team {} bot hack interrupted (the hacker is down)", team);
        }
      }
      continue;
    }
    const uint32_t thief = Load32(base, manager + kProtDataThief + team * 4);
    if (h.carrying)
    {
      PdzProtectionUnarmBot(ctx, base, character); // no shooting while carrying (log 075)
    }
    if (!h.carrying)
    {
      if (!IsGuestPointer(thief))
      {
        Call(ctx, base, sub_8244DAC0, manager, team);
        continue;
      }
      if (Distance(base, character, thief) < kFetchReach)
      {
        Call(ctx, base, sub_8244DB88, manager, team);
        h.carrying = true;
        if (Log())
        {
          REXLOG_INFO("pdz_scenario: Protection bots: team {} bot hacker {:08X} took the Data Thief", team, character);
        }
        continue;
      }
      SetRole(ctx, base, character, objective_bots::Role::Carrier, objective_bots::kGoalRoam, 0);
      HackerGoal(ctx, base, team, character, thief, "the Data Thief");
      HackerStillCheck(ctx, base, team, character, false, thief, false);
      continue;
    }
    if (!IsGuestPointer(terminal))
    {
      continue;
    }
    SetRole(ctx, base, character, objective_bots::Role::Carrier, objective_bots::kGoalRoam, 0);
    HackerGoal(ctx, base, team, character, terminal, "the terminal"); // Rare's goal 4 keeps it there
    const float distance = Distance(base, character, terminal);
    const auto event = h.hack.Update(kBotHack, distance, dt);
    HackerStillCheck(ctx, base, team, character, true, terminal, h.hack.Running());
    if (event != objective_bots::Action::Event::None && Log())
    {
      const double progress =
          event == objective_bots::Action::Event::Completed ? kBotHack.seconds : h.hack.Progress();
      REXLOG_INFO("pdz_scenario: Protection bots: team {} bot hack {} ({:.1f} s, {:.0f} cm from the terminal)", team,
                  objective_bots::EventName(event), progress, distance);
    }
    if (event == objective_bots::Action::Event::Completed)
    {
      h.carrying = false;
      g_hacker_target.erase(character);
      Call(ctx, base, sub_8244D518, manager, participant, terminal);
    }
  }

  // Roles for the other bots of each team.
  if (REXCVAR_GET(pdz_protection_objective_focus))
  {
    FocusRoles(ctx, base, manager, hackers, terminal);
    return;
  }
  for (uint32_t team = 0; team < uint32_t(kTeams); ++team)
  {
    uint32_t enemy = 0;
    for (uint32_t other = 0; other < uint32_t(kTeams) && !enemy; ++other)
    {
      if (other != team && IsGuestPointer(hackers[other]))
      {
        enemy = hackers[other];
      }
    }
    size_t index = 0;
    for (uint32_t p : TeamMembers(ctx, base, team))
    {
      const uint32_t bot = Load32(base, p + kParticipantCharacter);
      if (!IsBot(base, bot) || bot == hackers[team])
      {
        continue;
      }
      objective_bots::Role role = objective_bots::HelperRole(index++, enemy != 0);
      if (role == objective_bots::Role::Escort && !IsGuestPointer(hackers[team]))
      {
        role = objective_bots::Role::Guard;
      }
      StillCheck(ctx, base, bot, role);
      switch (role)
      {
      case objective_bots::Role::Escort:
        SetRole(ctx, base, bot, role, objective_bots::kGoalEscort, hackers[team]);
        break;
      case objective_bots::Role::Hunt:
        SetRole(ctx, base, bot, role, objective_bots::kGoalAttackCarrier, enemy);
        break;
      default:
        // Guarding the terminal needs a prop target (not possible yet):
        // guards stay with their hacker, else roam.
        if (IsGuestPointer(hackers[team]))
        {
          SetRole(ctx, base, bot, objective_bots::Role::Guard, objective_bots::kGoalEscort, hackers[team]);
        }
        else
        {
          SetRole(ctx, base, bot, objective_bots::Role::Guard, objective_bots::kGoalRoam, 0);
        }
        break;
      }
    }
  }
}

// --- Duel / Team Duel: the knockout bracket (pdz_mp_cut_scenarios_duel + pdz_duel_bracket; docs/DUEL_DESIGN.md) ---
// The design (28-29 Oct 2026), built from Rare's pieces: Rare's buy phase and round flow, its spawn-node
// lookup (each pair sent to its own laser-sealed zone), its kill key and touch-to-drop, its laser on / off, its
// holster routine and its bot goals. Zones come from Rare's arena table (82088F40); the pad graph with the beams'
// crossings cut is the check and gives each laser its two sides; a dropped border merges two zones. Host only.
REX_EXTERN(__imp__sub_82424AF0);
REX_EXTERN(__imp__sub_82424FD0);
REX_EXTERN(__imp__sub_8259D168);
REX_EXTERN(__imp__sub_82550CA0);
REX_EXTERN(__imp__sub_8259DAB8);
REX_EXTERN(sub_8259DE48); // laser on / off (laser, on): sets +924 0 / 2 and replicates
REX_EXTERN(sub_82550BA0); // key (character, key, on)

namespace
{
  constexpr uint32_t kLaserVtable = 0x820C6908;    // DP_LaserTripwire
  constexpr uint32_t kLaserState = 924;            // 0 on, 1 blinking, 2 off
  constexpr uint32_t kDuelSetupFilter = 22;        // setup +49: Duel only
  constexpr uint32_t kArenaTable = 0x82088F40;     // 5 arenas x 4 slots: Duel area ids
  constexpr uint32_t kAreaLists = 0x82D6BFD8;      // -> +144: per area (+20) a spawn pad list (end at +2048)
  constexpr uint32_t kDuelRotation = 17668;        // arena rotation (kDuelArena)
  constexpr uint32_t kSpawnLookupFfa = 0x82424F7C, kSpawnLookupTeam = 0x82424EA4;
  constexpr uint32_t kKeyAskTouch = 0x8259D8BC, kKeyAskColour = 0x8259DC44;
  constexpr double kStallSeconds = 60.0, kBackstopSeconds = 60.0;
  constexpr double kLeftSeconds = 15.0;                  // a human out of his zone: its bots hunt after this (log 298)
  constexpr double kGateRepath = 8.0, kGateStuck = 16.0; // a bot's gate walk without 1 m of progress (log 285)
  constexpr double kAutoDropSeconds = 20.0;              // a winner's border still up this long after the decision
  constexpr float kGateReach = 450.0f;    // cm: a bot this close (flat) to its gate laser opens it (logs 114, 120)
  constexpr float kNeutralBand = 1000.0f; // cm on foot: a pad about as near two of Rare's arenas is neither's
  constexpr float kNoDistance = 1e30f;

  struct DuelLaser
  {
    uint32_t prop = 0, setup = 0, group = 0;
    bool nokey = false;
    int cell[2] = {-1, -1};   // the cells on its two sides (the round's build, lasers up)
    int part[2] = {-1, -1};   // the zones of those cells now
    uint32_t pad[2] = {0, 0}; // a pad on each side, by the beam (a bot's walk to it)
    int links = 0;            // pad links its beam cuts (0: sides from samples by the beam)
  };

  // A cell: one piece of the pad graph with every laser up. A flood-fill part (the pads joined by links no beam
  // crosses) with one of Rare's arenas is one cell; one with several arenas (log 298, Old Town: {1-4, 13-20}, three
  // arenas joined without a laser) is split by walking distance into one cell per arena plus a neutral cell (the
  // pads about as near two arenas); a part without slots is a corridor.
  struct DuelCell
  {
    int arena = -1;       // Rare's arena (a row of 82088F40), -1: none
    bool neutral = false; // the pads between arenas joined without a laser
    int flood = -1;       // its flood-fill part
    std::vector<int> areas;
    size_t pads = 0;
    std::string name;
  };

  // A zone: cells joined by an open way (a laser off between them, or a plain link between two decided zones).
  struct DuelPart
  {
    std::vector<int> cells;
    std::vector<int> areas;
    size_t pads = 0;
    bool arena = false;     // holds one of Rare's arenas
    std::string key, name;
    std::vector<int> sides; // sides with players at home in it (participant index, or team in Team Duel)
    std::vector<uint32_t> chars;
    bool decided = false;
    bool kept = false;      // decided earlier and kept so
    int winner = -1;        // the winning side
  };

  struct GateWalk
  {
    uint32_t laser = 0, pad = 0;
    float best = kNoDistance; // closest to the pad so far (flat, cm)
    std::chrono::steady_clock::time_point progress{};
    bool repathed = false;
  };

  struct DuelMember
  {
    uint32_t participant = 0, character = 0;
    int side = -1, home = -1, here = -1; // cells
  };

  struct DuelBracket
  {
    uint32_t duel = 0;
    int round = 0;
    bool on = false; // this round runs the bracket (valid count, host)
    bool team = false;
    bool built = false;
    int lasers_on = -1;
    std::vector<DuelLaser> lasers;
    std::vector<DuelCell> cells;
    std::set<std::pair<int, int>> open; // cells joined by a plain link
    std::vector<int> place;             // arena cells in placement order
    std::vector<DuelPart> parts;        // the zones now
    std::vector<int> zone_of_cell;
    std::unordered_map<uint32_t, int> home;    // participant -> home cell (his arena at the fight's start)
    std::unordered_set<uint32_t> out;          // participants downed this round: out of the duel
    std::unordered_map<uint32_t, int> part_of; // character -> the zone he stands in
    std::unordered_map<uint32_t, int> home_of; // character -> his home cell's zone
    std::unordered_map<uint32_t, int> side_of; // character -> side
    std::unordered_set<uint32_t> holstered;
    std::unordered_map<uint32_t, GateWalk> gate;     // bot -> his walk to a gate
    std::unordered_map<uint32_t, uint32_t> gate_pad; // bot -> goal 4's pad (by his gate, or home)
    std::unordered_set<uint32_t> going_home;         // bots sent back to their zone
    std::unordered_set<uint32_t> hunting;            // bots on the stall hunt
    std::unordered_map<std::string, int> sticky;     // zone key -> the winning side, once decided with one
    std::unordered_map<std::string, std::chrono::steady_clock::time_point> undecided_since, left_since;
    std::unordered_set<std::string> kept_logged;
    std::unordered_map<int, bool> fighting;                                // side -> in an undecided zone last seen
    std::unordered_map<int, std::chrono::steady_clock::time_point> won_at; // side -> its latest win
    std::unordered_set<int> auto_done;                                     // sides whose win was auto-dropped
    std::unordered_set<int> empty_logged;                                  // arena cells logged empty
    std::chrono::steady_clock::time_point next_scan{}, phase2_at{};
    int phase = -1;
    bool backstop = false, start_logged = false;
    uint32_t scratch = 0; // guest vec3 for side samples
    // a touch being handled by Rare's laser update
    uint32_t touch_laser = 0, touch_char = 0, touch_group = 0;
    bool touch_pending = false;
    std::set<std::pair<uint32_t, uint32_t>> colour_logged;
  } g_br;

  thread_local uint32_t t_duel_laser = 0; // the laser whose update / draw runs

  bool BracketOn(const uint8_t *base)
  {
    return REXCVAR_GET(pdz_duel_bracket) && PdzDuelMatch(base) && g_br.on;
  }

  std::vector<uint32_t> DuelParticipants(PPCContext &ctx, uint8_t *base)
  {
    std::vector<uint32_t> out;
    for (uint32_t p = Load32(base, kParticipantList), n = 0; IsGuestPointer(p) && n < 64; p = Load32(base, p + 4), ++n)
    {
      if (g_br.duel && (Call(ctx, base, sub_82423588, g_br.duel, p) & 0xFF))
      {
        out.push_back(p);
      }
    }
    return out;
  }

  // The spawn pads of a Duel area: Rare's list, what 82424AF0 picks from ([82D6BFD8 + 144] + (area + 20) * 4,
  // its end pointer at +2048).
  std::vector<uint32_t> AreaPads(const uint8_t *base, int area)
  {
    std::vector<uint32_t> out;
    const uint32_t lists = Load32(base, kAreaLists + 144);
    const uint32_t list = IsGuestPointer(lists) ? Load32(base, lists + uint32_t(area + 20) * 4) : 0;
    if (!IsGuestPointer(list))
    {
      return out;
    }
    const uint32_t end = Load32(base, list + 2048);
    for (uint32_t e = list; e < end && e < list + 2048 && out.size() < 64; e += 4)
    {
      const uint32_t pad = Load32(base, e);
      if (IsGuestPointer(pad))
      {
        out.push_back(pad);
      }
    }
    return out;
  }

  std::unordered_map<uint32_t, int> g_br_pad_cell; // pad -> cell (the round's build, lasers up)
  std::unordered_map<uint32_t, int> g_br_pad_home; // pad -> the arena cell nearest on foot (a player's home there)

  int CellOfPad(uint32_t pad)
  {
    const auto it = g_br_pad_cell.find(pad);
    return it == g_br_pad_cell.end() ? -1 : it->second;
  }

  int ZoneOfCell(int cell)
  {
    return cell < 0 || size_t(cell) >= g_br.zone_of_cell.size() ? -1 : g_br.zone_of_cell[size_t(cell)];
  }

  float PadGap(const uint8_t *base, uint32_t a, uint32_t b)
  {
    const float dx = LoadFloat(base, a + 16) - LoadFloat(base, b + 16);
    const float dy = LoadFloat(base, a + 20) - LoadFloat(base, b + 20);
    const float dz = LoadFloat(base, a + 24) - LoadFloat(base, b + 24);
    return std::sqrt(dx * dx + dy * dy + dz * dz);
  }

  // Flat distance from an object's position (+kPosition) to a pad.
  float FlatToPad(const uint8_t *base, uint32_t object, uint32_t pad)
  {
    const float dx = LoadFloat(base, object + kPosition) - LoadFloat(base, pad + 16);
    const float dz = LoadFloat(base, object + kPosition + 8) - LoadFloat(base, pad + 24);
    return std::sqrt(dx * dx + dz * dz);
  }

  bool LaserUp(const uint8_t *base, const DuelLaser &l)
  {
    return Load32(base, l.prop + kLaserState) != 2;
  }

  uint32_t ScratchAt(uint8_t *base, float x, float y, float z)
  {
    if (!g_br.scratch && !(g_br.scratch = REX_KERNEL_MEMORY()->SystemHeapAlloc(16)))
    {
      return 0;
    }
    StoreFloat(base, g_br.scratch, x);
    StoreFloat(base, g_br.scratch + 4, y);
    StoreFloat(base, g_br.scratch + 8, z);
    return g_br.scratch;
  }

  std::string AreaList(const std::vector<int> &areas)
  {
    std::string s;
    for (const int a : areas)
    {
      s += fmt::format("{}{}", s.empty() ? "" : ",", a);
    }
    return "{" + s + "}";
  }

  // Log 114: an active laser does not show in the links' closed count (+14), so the zones come from a model, as
  // tools/duel/duel_map.py builds them: a link is cut while it crosses an active beam (flat, half length kBeamHalf,
  // within 2.5 m of its height).
  constexpr float kBeamHalf = 450.0f;

  struct Beam
  {
    float x0, z0, x1, z1, y;
  };

  bool Crosses(float ax, float az, float bx, float bz, const Beam &e)
  {
    const auto side = [](float px, float pz, float qx, float qz, float rx, float rz) {
      return (qx - px) * (rz - pz) - (qz - pz) * (rx - px);
    };
    const float d1 = side(e.x0, e.z0, e.x1, e.z1, ax, az), d2 = side(e.x0, e.z0, e.x1, e.z1, bx, bz);
    const float d3 = side(ax, az, bx, bz, e.x0, e.z0), d4 = side(ax, az, bx, bz, e.x1, e.z1);
    return ((d1 > 0) != (d2 > 0)) && ((d3 > 0) != (d4 > 0));
  }

  int Root(std::vector<int> &uf, int x)
  {
    while (uf[size_t(x)] != x)
    {
      x = uf[size_t(x)] = uf[size_t(uf[size_t(x)])];
    }
    return x;
  }

  // The zones from the cells: a laser off between two cells joins them (dropped by a winner, the backstop or Rare);
  // with `joins`, two zones joined by a plain link (no laser) become one once both are decided: an open corridor
  // between two winners, or a winner and an empty zone. Sides are counted where the players are at home (their cell
  // at the fight's start), so a player who walks out of his arena still belongs to its duel. A zone decided with a
  // winner stays decided (log 285: a revive reopened one); downed players are out of the duel anyway (Members).
  void Rezone(const uint8_t *base, const std::vector<DuelMember> &members, bool joins)
  {
    const size_t n = g_br.cells.size();
    std::vector<int> uf(n);
    for (size_t i = 0; i < n; ++i)
    {
      uf[i] = int(i);
    }
    const auto join = [&](int a, int b) {
      a = Root(uf, a);
      b = Root(uf, b);
      if (a != b)
      {
        uf[size_t(std::max(a, b))] = std::min(a, b);
      }
    };
    for (const DuelLaser &l : g_br.lasers)
    {
      if (!LaserUp(base, l) && l.cell[0] >= 0 && l.cell[1] >= 0 && l.cell[0] != l.cell[1])
      {
        join(l.cell[0], l.cell[1]);
      }
    }
    for (size_t pass = 0; pass <= n; ++pass)
    {
      g_br.parts.clear();
      g_br.zone_of_cell.assign(n, -1);
      std::map<int, int> zone_of_root;
      for (size_t c = 0; c < n; ++c)
      {
        const auto [it, made] = zone_of_root.emplace(Root(uf, int(c)), int(g_br.parts.size()));
        if (made)
        {
          g_br.parts.emplace_back();
        }
        g_br.zone_of_cell[c] = it->second;
        g_br.parts[size_t(it->second)].cells.push_back(int(c));
      }
      for (DuelPart &z : g_br.parts)
      {
        for (const int c : z.cells)
        {
          const DuelCell &cell = g_br.cells[size_t(c)];
          z.areas.insert(z.areas.end(), cell.areas.begin(), cell.areas.end());
          z.pads += cell.pads;
          z.arena = z.arena || cell.arena >= 0;
          z.key += fmt::format("{}{}", z.key.empty() ? "" : ",", c);
          z.name += (z.name.empty() ? "" : "+") + cell.name;
        }
        std::sort(z.areas.begin(), z.areas.end());
      }
      for (const DuelMember &m : members)
      {
        const int zi = ZoneOfCell(m.home);
        if (zi < 0)
        {
          continue;
        }
        DuelPart &z = g_br.parts[size_t(zi)];
        z.chars.push_back(m.character);
        if (std::find(z.sides.begin(), z.sides.end(), m.side) == z.sides.end())
        {
          z.sides.push_back(m.side);
        }
      }
      for (DuelPart &z : g_br.parts)
      {
        z.decided = z.sides.size() <= 1;
        z.winner = z.sides.size() == 1 ? z.sides.front() : -1;
        const auto sticky = g_br.sticky.find(z.key);
        if (!z.decided && sticky != g_br.sticky.end())
        {
          z.decided = true;
          z.kept = true;
          z.winner = sticky->second;
        }
      }
      bool changed = false;
      for (const auto &[a, b] : g_br.open)
      {
        const int za = g_br.zone_of_cell[size_t(a)], zb = g_br.zone_of_cell[size_t(b)];
        if (joins && za != zb && g_br.parts[size_t(za)].decided && g_br.parts[size_t(zb)].decided)
        {
          join(a, b);
          changed = true;
        }
      }
      if (!changed)
      {
        break;
      }
    }
    for (DuelLaser &l : g_br.lasers)
    {
      for (int s = 0; s < 2; ++s)
      {
        l.part[s] = ZoneOfCell(l.cell[s]);
      }
    }
  }

  // The round's cells, built once with every laser up (Rare switches them all on at the round start, 82424D00).
  // Zones come from Rare's arenas (table 82088F40); the flood fill of the pad graph with the beams' crossings cut
  // is the check, and where it joins several arenas without a laser (log 298) Rare's arenas are used and the pads
  // between them are neutral. Each laser's two sides are the cells at the two ends of the pad links its beam cuts
  // (log 285: the old samples 2 m either side of the beam left 20 of 32 lasers on no border).
  void BuildCells(PPCContext &ctx, uint8_t *base)
  {
    g_br.cells.clear();
    g_br.lasers.clear();
    g_br.open.clear();
    g_br.place.clear();
    g_br_pad_cell.clear();
    g_br_pad_home.clear();
    if (const uint32_t world = Load32(base, kGameWorld); IsGuestPointer(world))
    {
      const uint32_t end = Load32(base, world + kWorldEnd);
      uint32_t node = Load32(base, world + kWorldFirst);
      for (int guard = 0; IsGuestPointer(node) && node != end && guard < 16384; ++guard)
      {
        const uint32_t object = Load32(base, node + 4);
        node = Load32(base, node + 12);
        const uint32_t setup =
            IsGuestPointer(object) && Load32(base, object) == kLaserVtable ? Load32(base, object + kPropSetup) : 0;
        if (IsGuestPointer(setup) && base[setup + kSetupModeFilter] == kDuelSetupFilter)
        {
          DuelLaser l;
          l.prop = object;
          l.setup = setup;
          l.group = Load32(base, setup);
          l.nokey = base[setup + 144] != 0;
          g_br.lasers.push_back(l);
        }
      }
    }
    std::vector<Beam> beams;
    std::vector<size_t> beam_laser;
    int on = 0;
    for (size_t i = 0; i < g_br.lasers.size(); ++i)
    {
      const DuelLaser &l = g_br.lasers[i];
      if (!LaserUp(base, l))
      {
        continue;
      }
      ++on;
      const float yaw = LoadFloat(base, l.setup + 20) * 3.14159265f / 180.0f;
      const float cx = LoadFloat(base, l.prop + kPosition), cz = LoadFloat(base, l.prop + kPosition + 8);
      beams.push_back(Beam{cx - kBeamHalf * std::cos(yaw), cz + kBeamHalf * std::sin(yaw),
                           cx + kBeamHalf * std::cos(yaw), cz - kBeamHalf * std::sin(yaw),
                           LoadFloat(base, l.prop + kPosition + 4)});
      beam_laser.push_back(i);
    }
    g_br.lasers_on = on;
    // Rare's arenas: each area's row in the table.
    int arena_of[21];
    std::fill(std::begin(arena_of), std::end(arena_of), -1);
    for (int a = 0; a < 5; ++a)
    {
      for (int s = 0; s < 4; ++s)
      {
        const int area = int(Load32(base, kArenaTable + uint32_t(a * 4 + s) * 4));
        if (area >= 1 && area <= 20)
        {
          arena_of[area] = a;
        }
      }
    }
    // Seeds: every spawn pad of every area.
    std::vector<std::pair<int, uint32_t>> seeds;
    std::unordered_map<uint32_t, int> seed_area;
    for (int area = 1; area <= 20; ++area)
    {
      for (const uint32_t pad : AreaPads(base, area))
      {
        seeds.emplace_back(area, pad);
        seed_area.emplace(pad, area);
      }
    }
    // The pad set (everything the seeds reach) and its edges (walkable links, both ways), cut where an up beam
    // crosses; each cut is noted on its laser.
    std::unordered_map<uint32_t, std::vector<uint32_t>> adj;
    std::vector<uint32_t> queue;
    std::vector<std::vector<std::pair<uint32_t, uint32_t>>> cuts(g_br.lasers.size());
    for (const auto &seed : seeds)
    {
      if (adj.emplace(seed.second, std::vector<uint32_t>{}).second)
      {
        queue.push_back(seed.second);
      }
    }
    for (size_t i = 0; i < queue.size() && queue.size() < 16384; ++i)
    {
      const uint32_t pad = queue[i];
      uint32_t link = Load32(base, pad + 8);
      for (int k = 0; IsGuestPointer(link) && k < 32; ++k, link = Load32(base, link + 4))
      {
        const uint32_t to = Load32(base, link);
        if (!IsGuestPointer(to) || !base[link + 15])
        {
          continue; // a line-of-sight link (Rare's A* never walks one)
        }
        if (adj.emplace(to, std::vector<uint32_t>{}).second)
        {
          queue.push_back(to);
        }
        const float ax = LoadFloat(base, pad + 16), ay = LoadFloat(base, pad + 20), az = LoadFloat(base, pad + 24);
        const float bx = LoadFloat(base, to + 16), by = LoadFloat(base, to + 20), bz = LoadFloat(base, to + 24);
        bool cut = false;
        for (size_t e = 0; e < beams.size(); ++e)
        {
          if (std::fabs((ay + by) * 0.5f - beams[e].y) <= 250.0f && Crosses(ax, az, bx, bz, beams[e]))
          {
            cut = true;
            if (cuts[beam_laser[e]].size() < 256)
            {
              cuts[beam_laser[e]].emplace_back(pad, to);
            }
          }
        }
        if (!cut)
        {
          adj[pad].push_back(to);
          adj[to].push_back(pad);
        }
      }
    }
    // The flood fill (the check): parts of the graph with every laser up.
    std::unordered_map<uint32_t, int> flood;
    int floods = 0;
    for (const uint32_t start : queue)
    {
      if (!flood.emplace(start, floods).second)
      {
        continue;
      }
      std::vector<uint32_t> stack{start};
      while (!stack.empty())
      {
        const uint32_t a = stack.back();
        stack.pop_back();
        for (const uint32_t b : adj[a])
        {
          if (flood.emplace(b, floods).second)
          {
            stack.push_back(b);
          }
        }
      }
      ++floods;
    }
    std::vector<std::set<int>> arenas_in(static_cast<size_t>(floods));
    for (const auto &[area, pad] : seeds)
    {
      const auto f = flood.find(pad);
      if (arena_of[area] >= 0 && f != flood.end())
      {
        arenas_in[size_t(f->second)].insert(arena_of[area]);
      }
    }
    // Walking distance from each arena's spawn pads, in the parts that hold several arenas.
    std::map<int, std::unordered_map<uint32_t, float>> dist;
    for (const auto &[area, pad] : seeds)
    {
      const auto f = flood.find(pad);
      if (arena_of[area] >= 0 && f != flood.end() && arenas_in[size_t(f->second)].size() >= 2)
      {
        dist[arena_of[area]].emplace(pad, 0.0f);
      }
    }
    for (auto &[arena, d] : dist)
    {
      using Item = std::pair<float, uint32_t>;
      std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
      for (const auto &[pad, zero] : d)
      {
        pq.emplace(zero, pad);
      }
      while (!pq.empty())
      {
        const Item top = pq.top();
        pq.pop();
        if (top.first > d[top.second])
        {
          continue;
        }
        for (const uint32_t b : adj[top.second])
        {
          const float nd = top.first + PadGap(base, top.second, b);
          const auto it = d.find(b);
          if (it == d.end() || nd < it->second)
          {
            d[b] = nd;
            pq.emplace(nd, b);
          }
        }
      }
    }
    // Cells.
    std::map<std::pair<int, int>, int> cell_ids; // (flood part, arena; -1 neutral / corridor) -> cell
    const auto cell_for = [&](int f, int arena) {
      const auto [it, made] = cell_ids.emplace(std::pair<int, int>{f, arena}, int(g_br.cells.size()));
      if (made)
      {
        DuelCell c;
        c.flood = f;
        c.arena = arena;
        c.neutral = arena < 0 && !arenas_in[size_t(f)].empty();
        g_br.cells.push_back(c);
      }
      return it->second;
    };
    for (const uint32_t pad : queue)
    {
      const int f = flood[pad];
      const std::set<int> &ar = arenas_in[size_t(f)];
      int cell = -1, home = -1;
      if (ar.size() <= 1)
      {
        cell = home = cell_for(f, ar.empty() ? -1 : *ar.begin());
      }
      else
      {
        int a1 = -1;
        float d1 = kNoDistance, d2 = kNoDistance;
        for (const int a : ar)
        {
          const auto &d = dist[a];
          const auto it = d.find(pad);
          const float x = it == d.end() ? kNoDistance : it->second;
          if (x < d1)
          {
            d2 = d1;
            d1 = x;
            a1 = a;
          }
          else if (x < d2)
          {
            d2 = x;
          }
        }
        const auto seed = seed_area.find(pad);
        const bool spawn = seed != seed_area.end() && arena_of[seed->second] >= 0;
        if (spawn)
        {
          a1 = arena_of[seed->second]; // a spawn pad keeps its arena
        }
        home = a1 >= 0 ? cell_for(f, a1) : -1;
        cell = a1 >= 0 && (spawn || (d1 < kNoDistance && d2 - d1 >= kNeutralBand)) ? home : cell_for(f, -1);
      }
      g_br_pad_cell[pad] = cell;
      if (home >= 0)
      {
        g_br_pad_home[pad] = home;
      }
    }
    // No two arena cells touch: a pad linked to another arena's cell goes neutral (spawn pads stay).
    std::vector<uint32_t> to_neutral;
    for (const uint32_t pad : queue)
    {
      const int c = g_br_pad_cell[pad];
      if (g_br.cells[size_t(c)].arena < 0 || seed_area.count(pad))
      {
        continue;
      }
      for (const uint32_t b : adj[pad])
      {
        const int cb = g_br_pad_cell[b];
        if (cb != c && g_br.cells[size_t(cb)].arena >= 0)
        {
          to_neutral.push_back(pad);
          break;
        }
      }
    }
    for (const uint32_t pad : to_neutral)
    {
      g_br_pad_cell[pad] = cell_for(flood[pad], -1);
    }
    for (const auto &[pad, c] : g_br_pad_cell)
    {
      (void)pad;
      ++g_br.cells[size_t(c)].pads;
    }
    for (const auto &[area, pad] : seeds)
    {
      const int c = CellOfPad(pad);
      if (c >= 0)
      {
        std::vector<int> &areas = g_br.cells[size_t(c)].areas;
        if (std::find(areas.begin(), areas.end(), area) == areas.end())
        {
          areas.push_back(area);
        }
      }
    }
    for (size_t i = 0; i < g_br.cells.size(); ++i)
    {
      DuelCell &c = g_br.cells[i];
      std::sort(c.areas.begin(), c.areas.end());
      c.name = !c.areas.empty() ? fmt::format("c{} {}", i, AreaList(c.areas))
                                : fmt::format("c{} {}({} pads)", i, c.neutral ? "neutral" : "corridor", c.pads);
    }
    for (const uint32_t pad : queue)
    {
      for (const uint32_t b : adj[pad])
      {
        const int a = g_br_pad_cell[pad], c = g_br_pad_cell[b];
        if (a != c)
        {
          g_br.open.emplace(std::min(a, c), std::max(a, c));
        }
      }
    }
    // Laser sides: the cells most of its cut links join; else samples 2 m either side of the beam.
    for (size_t i = 0; i < g_br.lasers.size(); ++i)
    {
      DuelLaser &l = g_br.lasers[i];
      l.links = int(cuts[i].size());
      std::map<std::pair<int, int>, int> votes;
      for (const auto &[a, b] : cuts[i])
      {
        const int ca = CellOfPad(a), cb = CellOfPad(b);
        if (ca >= 0 && cb >= 0 && ca != cb)
        {
          ++votes[{std::min(ca, cb), std::max(ca, cb)}];
        }
      }
      if (!votes.empty())
      {
        const auto best = std::max_element(votes.begin(), votes.end(),
                                           [](const auto &x, const auto &y) { return x.second < y.second; });
        l.cell[0] = best->first.first;
        l.cell[1] = best->first.second;
        for (int s = 0; s < 2; ++s)
        {
          float near = kNoDistance;
          for (const auto &[a, b] : cuts[i])
          {
            for (const uint32_t p : {a, b})
            {
              if (CellOfPad(p) == l.cell[s] && FlatToPad(base, l.prop, p) < near)
              {
                near = FlatToPad(base, l.prop, p);
                l.pad[s] = p;
              }
            }
          }
        }
        continue;
      }
      l.links = 0;
      const float yaw = LoadFloat(base, l.setup + 20) * 3.14159265f / 180.0f;
      const float nx = std::sin(yaw), nz = std::cos(yaw);
      const float cx = LoadFloat(base, l.prop + kPosition), cy = LoadFloat(base, l.prop + kPosition + 4),
                  cz = LoadFloat(base, l.prop + kPosition + 8);
      for (int s = 0; s < 2; ++s)
      {
        const float k = s ? -200.0f : 200.0f;
        uint32_t pad = 0;
        for (const float radius : {250.0f, 500.0f})
        {
          if (!pad)
          {
            if (const uint32_t at = ScratchAt(base, cx + k * nx, cy, cz + k * nz))
            {
              pad = RarePadWithin(ctx, base, at, radius);
            }
          }
        }
        l.pad[s] = pad;
        l.cell[s] = pad ? CellOfPad(pad) : -1;
      }
      if (l.cell[0] == l.cell[1])
      {
        l.cell[1] = -1; // both samples on one side: the other side unknown
      }
    }
    // Placement: each arena's main cell (the most areas), spread over the flood-fill parts first.
    std::map<int, int> main_cell; // arena -> cell
    for (size_t i = 0; i < g_br.cells.size(); ++i)
    {
      const DuelCell &c = g_br.cells[i];
      if (c.arena >= 0 && (!main_cell.count(c.arena) ||
                           c.areas.size() > g_br.cells[size_t(main_cell[c.arena])].areas.size()))
      {
        main_cell[c.arena] = int(i);
      }
    }
    for (const size_t need : {size_t(2), size_t(1)})
    {
      std::map<int, std::vector<int>> per_flood;
      for (const auto &[arena, c] : main_cell)
      {
        (void)arena;
        if (g_br.cells[size_t(c)].areas.size() >= need)
        {
          per_flood[g_br.cells[size_t(c)].flood].push_back(c);
        }
      }
      for (size_t rank = 0; rank < 8; ++rank)
      {
        bool any = false;
        for (const auto &[f, list] : per_flood)
        {
          (void)f;
          if (rank < list.size())
          {
            g_br.place.push_back(list[rank]);
            any = true;
          }
        }
        if (!any)
        {
          break;
        }
      }
      if (!g_br.place.empty())
      {
        break;
      }
    }
    g_br.built = true;
    Rezone(base, {}, false); // one zone per cell until the fight
  }

  // The round's cells: each flood-fill part against Rare's arenas.
  std::string CellReport()
  {
    std::map<int, std::vector<int>> by_flood, by_arena;
    for (size_t i = 0; i < g_br.cells.size(); ++i)
    {
      by_flood[g_br.cells[i].flood].push_back(int(i));
      if (g_br.cells[i].arena >= 0)
      {
        by_arena[g_br.cells[i].arena].push_back(int(i));
      }
    }
    std::string s;
    for (const auto &[f, list] : by_flood)
    {
      (void)f;
      std::vector<int> areas;
      size_t pads = 0;
      int arenas = 0;
      std::string inner;
      for (const int c : list)
      {
        const DuelCell &cell = g_br.cells[size_t(c)];
        areas.insert(areas.end(), cell.areas.begin(), cell.areas.end());
        pads += cell.pads;
        arenas += cell.arena >= 0;
        inner += fmt::format("{}{}{}", inner.empty() ? "" : ", ", cell.name,
                             cell.arena >= 0 ? fmt::format(" (Rare's arena {}, {} pads)", cell.arena, cell.pads)
                                             : std::string());
      }
      if (areas.empty())
      {
        continue; // corridors: see the borders
      }
      std::sort(areas.begin(), areas.end());
      s += fmt::format("{}flood fill {} ({} pads){}: {}", s.empty() ? "" : "; ", AreaList(areas), pads,
                       arenas >= 2 ? fmt::format(" DISAGREES: it holds {} of Rare's arenas joined without a laser; Rare's "
                                                 "arenas used, the pads between them neutral",
                                                 arenas)
                                   : std::string(" = Rare's arena"),
                       inner);
    }
    for (const auto &[arena, list] : by_arena)
    {
      if (list.size() > 1)
      {
        std::string cells;
        for (const int c : list)
        {
          cells += (cells.empty() ? "" : ", ") + g_br.cells[size_t(c)].name;
        }
        s += fmt::format("; Rare's arena {} is split by lasers: {}", arena, cells);
      }
    }
    std::string place;
    for (const int c : g_br.place)
    {
      place += (place.empty() ? "" : ", ") + g_br.cells[size_t(c)].name;
    }
    return s + "; pairs go to: " + (place.empty() ? std::string("none (Rare's placement)") : place);
  }

  // A laser is on zone z's border when exactly one of its sides is in z (the other: another zone, a corridor, or
  // not found). Corridors never block: a laser between a corridor and a zone is that zone's.
  bool OnBorderOf(const DuelLaser &l, int z)
  {
    return z >= 0 && ((l.part[0] == z) != (l.part[1] == z));
  }

  std::string ZoneName(int z)
  {
    return z < 0 || size_t(z) >= g_br.parts.size() ? std::string("none (side not found)") : g_br.parts[size_t(z)].name;
  }

  // Zone z's border now: the keyed lasers up per neighbour, and the permanent ones.
  std::string BorderOf(const uint8_t *base, int z, int *keyed_out = nullptr)
  {
    std::map<int, std::vector<uint32_t>> per;
    int keyed = 0, permanent = 0;
    for (const DuelLaser &l : g_br.lasers)
    {
      if (!LaserUp(base, l) || !OnBorderOf(l, z))
      {
        continue;
      }
      if (l.nokey)
      {
        ++permanent;
        continue;
      }
      per[l.part[0] == z ? l.part[1] : l.part[0]].push_back(l.group);
      ++keyed;
    }
    if (keyed_out)
    {
      *keyed_out = keyed;
    }
    std::string s;
    for (const auto &[other, groups] : per)
    {
      std::string g;
      for (const uint32_t x : groups)
      {
        g += fmt::format("{}{}", g.empty() ? "" : " ", x);
      }
      s += fmt::format("{}to {}: {} (groups {})", s.empty() ? "" : ", ", ZoneName(other), groups.size(), g);
    }
    return fmt::format("{} keyed laser(s){}{}, {} permanent (no key)", keyed, s.empty() ? "" : ": ", s, permanent);
  }

  std::string ZoneList()
  {
    std::string s;
    for (size_t i = 0; i < g_br.parts.size(); ++i)
    {
      const DuelPart &z = g_br.parts[i];
      if (!z.arena && z.chars.empty())
      {
        continue;
      }
      s += fmt::format("{}zone {} {} ({} pads, {})", s.empty() ? "" : "; ", i, z.name, z.pads,
                       !z.decided        ? std::string("undecided")
                       : z.winner >= 0   ? fmt::format("decided: winner side {}", z.winner)
                                         : std::string("decided: empty"));
    }
    return s;
  }

  const DuelLaser *FindDuelLaser(uint32_t prop)
  {
    for (const DuelLaser &l : g_br.lasers)
    {
      if (l.prop == prop)
      {
        return &l;
      }
    }
    return nullptr;
  }

  // For this character: the winner of his zone (decided, his side), and the laser is on its border. Every keyed
  // laser of the zone's border is then openable for him (green), whatever is behind it.
  bool OpenableFor(const DuelLaser &l, const uint8_t *base, uint32_t character)
  {
    if (l.nokey || !LaserUp(base, l))
    {
      return false;
    }
    const auto home = g_br.home_of.find(character);
    const auto side = g_br.side_of.find(character);
    if (home == g_br.home_of.end() || side == g_br.side_of.end() || home->second < 0 ||
        size_t(home->second) >= g_br.parts.size())
    {
      return false;
    }
    const DuelPart &z = g_br.parts[size_t(home->second)];
    return z.arena && z.decided && z.winner == side->second && OnBorderOf(l, home->second);
  }

  std::string NameOf(const uint8_t *base, uint32_t character)
  {
    return fmt::format("{:08X} ({})", character, IsBot(base, character) ? BotName(base, character) : "player");
  }

  // Every keyed laser between the opener's zone and the zone behind this laser goes off, one by one (not Rare's whole
  // group). The opener keeps his key when the other side is empty or a corridor (a bye), else it is used (Rare's rule;
  // a bot's arrival is ours).
  void DropBorder(PPCContext &ctx, uint8_t *base, uint32_t prop, uint32_t opener, const char *how)
  {
    const DuelLaser *l = FindDuelLaser(prop);
    if (!l)
    {
      return;
    }
    const auto home = g_br.home_of.find(opener);
    int mine = home == g_br.home_of.end() ? -1 : home->second;
    if (mine != l->part[0] && mine != l->part[1])
    {
      mine = l->part[0] >= 0 ? l->part[0] : l->part[1];
    }
    const int other = l->part[0] == mine ? l->part[1] : l->part[0];
    int dropped = 0;
    for (const DuelLaser &o : g_br.lasers)
    {
      if (o.nokey || !OnBorderOf(o, mine) || (o.part[0] == mine ? o.part[1] : o.part[0]) != other)
      {
        continue;
      }
      if (LaserUp(base, o))
      {
        Call(ctx, base, sub_8259DE48, o.prop, 0);
      }
      ++dropped;
    }
    const bool rare_touch = std::strcmp(how, "Rare's touch") == 0;
    const bool bye = other < 0 || size_t(other) >= g_br.parts.size() || g_br.parts[size_t(other)].sides.empty();
    if (bye)
    {
      Call(ctx, base, sub_82550BA0, opener, 1, 1); // passing an empty zone or a corridor counts as winning it
    }
    else if (!rare_touch)
    {
      Call(ctx, base, sub_82550BA0, opener, 1, 0);
      mp_announcer::Line(ctx, base, "XACT_SOUNDBANK_MULTIPLAYER_DO_FORCEFIELD_DOWN", "Duel gate opened by a bot");
    }
    if (Log())
    {
      REXLOG_INFO("pdz_scenario: Duel bracket: zone {} vs {}: border lasers ({}) dropped by {} ({}){}", ZoneName(mine),
                  ZoneName(other), dropped, NameOf(base, opener), how, bye ? "; a bye: he keeps his key" : "");
    }
    g_br.gate.erase(opener);
    g_br.gate_pad.erase(opener);
    if (IsBot(base, opener))
    {
      objective_bots::SetGoal(ctx, base, opener, objective_bots::kGoalRoam, 0);
    }
  }

  void DuelReleaseBot(PPCContext &ctx, uint8_t *base, uint32_t bot)
  {
    const bool ours = g_br.gate.erase(bot) + g_br.hunting.erase(bot) + g_br.going_home.erase(bot) > 0;
    g_br.gate_pad.erase(bot);
    if (ours && IsBot(base, bot) && !objective_bots::CharacterDown(ctx, base, bot))
    {
      objective_bots::SetGoal(ctx, base, bot, objective_bots::kGoalRoam, 0);
    }
  }

  // Sends a bot on Rare's goal 4 to a pad (PdzDuelGatePad answers goal 4's pad lookup); roam first so it re-plans.
  void WalkTo(PPCContext &ctx, uint8_t *base, uint32_t bot, uint32_t pad)
  {
    g_br.gate_pad[bot] = pad;
    Store32(base, bot + kBotGoalTeam, 0);
    objective_bots::SetGoal(ctx, base, bot, objective_bots::kGoalRoam, 0);
    objective_bots::SetGoal(ctx, base, bot, kGoalFetch, 0);
  }

  // The duel's players alive now. Downed counts as dead for the duel (log 285: Rare's revive brought a loser back
  // and reopened his zone): once down, a participant is out until the next round, revived or not.
  std::vector<DuelMember> Members(PPCContext &ctx, uint8_t *base, std::vector<uint32_t> &revived)
  {
    std::vector<DuelMember> out;
    for (const uint32_t p : DuelParticipants(ctx, base))
    {
      const uint32_t c = Load32(base, p + kParticipantCharacter);
      if (!IsGuestPointer(c))
      {
        continue;
      }
      if (base[p + kParticipantDead] || objective_bots::CharacterDown(ctx, base, c))
      {
        if (g_br.out.insert(p).second && Log())
        {
          REXLOG_INFO("pdz_scenario: Duel bracket: {} down: out of the duel this round (a revive doesn't bring him back)",
                      NameOf(base, c));
        }
        continue;
      }
      if (g_br.out.count(p))
      {
        revived.push_back(c);
        continue;
      }
      DuelMember m;
      m.participant = p;
      m.character = c;
      m.side = g_br.team ? ParticipantTeam(ctx, base, p) : int(Load32(base, p + kParticipantIndex));
      uint32_t pad = 0;
      for (const float radius : {300.0f, 800.0f})
      {
        if (!pad)
        {
          pad = RarePadWithin(ctx, base, c + kPosition, radius);
          pad = CellOfPad(pad) >= 0 ? pad : 0;
        }
      }
      m.here = pad ? CellOfPad(pad) : -1;
      auto h = g_br.home.find(p);
      if (h == g_br.home.end() && pad)
      {
        const auto ph = g_br_pad_home.find(pad);
        const int home = ph != g_br_pad_home.end() ? ph->second : m.here;
        if (home >= 0)
        {
          h = g_br.home.emplace(p, home).first;
        }
      }
      m.home = h == g_br.home.end() ? -1 : h->second;
      out.push_back(m);
    }
    return out;
  }
} // namespace

// From the round start hook (sub_82424B80) on entry: a new round's bracket.
void PdzDuelBracketRoundStart(PPCContext &ctx, uint8_t *base, uint32_t duel)
{
  std::vector<uint32_t> ours;
  for (const auto &[bot, walk] : g_br.gate)
  {
    (void)walk;
    ours.push_back(bot);
  }
  ours.insert(ours.end(), g_br.going_home.begin(), g_br.going_home.end());
  for (const uint32_t bot : ours)
  {
    if (IsBot(base, bot) && !objective_bots::CharacterDown(ctx, base, bot))
    {
      objective_bots::SetGoal(ctx, base, bot, objective_bots::kGoalRoam, 0);
    }
  }
  const uint32_t scratch = g_br.scratch;
  const int round = g_br.duel == duel ? g_br.round + 1 : 1;
  g_br = DuelBracket{};
  g_br.scratch = scratch;
  g_br.duel = duel;
  g_br.round = round;
  if (!REXCVAR_GET(pdz_duel_bracket) || !PdzDuelMatch(base))
  {
    return;
  }
  const uint32_t session = Load32(base, 0x82E34210);
  if (!IsGuestPointer(session) || !base[session + 36])
  {
    return; // clients: the host runs the bracket
  }
  const uint32_t settings = Load32(base, kMatchSettings);
  g_br.team = IsGuestPointer(settings) && base[settings + kSettingsTeams] > 0;
  const auto players = DuelParticipants(ctx, base);
  const size_t n = players.size();
  bool valid = n == 2 || n == 4 || n == 8;
  std::string teams;
  if (g_br.team)
  {
    std::map<int, int> per;
    for (const uint32_t p : players)
    {
      ++per[ParticipantTeam(ctx, base, p)];
    }
    for (const auto &[t, k] : per)
    {
      teams += fmt::format("{}team {}: {}", teams.empty() ? " (" : ", ", t, k);
    }
    teams += teams.empty() ? "" : ")";
    valid = per.size() == 2 && per.begin()->second == per.rbegin()->second &&
            (per.begin()->second == 2 || per.begin()->second == 4);
  }
  g_br.on = valid;
  if (Log())
  {
    REXLOG_INFO("pdz_scenario: Duel bracket: round {}: {} {} player(s){}{}", round, g_br.team ? "Team Duel" : "Duel", n,
                teams,
                valid ? "" : ": NOT a supported count (Duel 2 / 4 / 8, Team Duel 2 teams of 2 or 4): Rare's Duel this round");
  }
}

// After Rare's round start: humans get key 1 (pdz_test_duel_key), the zones are logged.
void PdzDuelBracketRoundStarted(PPCContext &ctx, uint8_t *base)
{
  if (REXCVAR_GET(pdz_test_duel_key) && PdzDuelMatch(base))
  {
    for (const uint32_t p : DuelParticipants(ctx, base))
    {
      const uint32_t c = Load32(base, p + kParticipantCharacter);
      if (IsGuestPointer(c) && Load32(base, p + 944) == 2)
      {
        Call(ctx, base, sub_82550BA0, c, 1, 1);
        REXLOG_INFO("pdz_scenario: Duel test: player {:08X} given key 1 (pdz_test_duel_key)", c);
      }
    }
  }
  if (!BracketOn(base))
  {
    return;
  }
  if (!g_br.built)
  {
    BuildCells(ctx, base);
  }
  if (Log())
  {
    int by_links = 0, by_samples = 0, unsided = 0;
    for (const DuelLaser &l : g_br.lasers)
    {
      if (l.cell[0] < 0 || l.cell[1] < 0)
      {
        ++unsided;
      }
      else if (l.links > 0)
      {
        ++by_links;
      }
      else
      {
        ++by_samples;
      }
    }
    REXLOG_INFO("pdz_scenario: Duel bracket: round {} zones (lasers up, {} of {} on): {}", g_br.round, g_br.lasers_on,
                g_br.lasers.size(), CellReport());
    std::string borders;
    for (size_t z = 0; z < g_br.parts.size(); ++z)
    {
      if (g_br.parts[z].arena)
      {
        borders += fmt::format("{}{}: {}", borders.empty() ? "" : "; ", g_br.parts[z].name, BorderOf(base, int(z)));
      }
    }
    REXLOG_INFO("pdz_scenario: Duel bracket: round {} border lasers per zone (sides from the pad links each beam cuts: {}, "
                "from samples by the beam: {}, a side not found: {}): {}",
                g_br.round, by_links, by_samples, unsided, borders.empty() ? std::string("none") : borders);
  }
}

// sub_82424AF0 (duel, arena, slot column): a player's spawn node for this round. From the round start's placement,
// each pair is sent to one of Rare's arenas (its cell; the round's set rotates with the rounds), the two sides to
// two different areas of it.
REX_HOOK_RAW(sub_82424AF0)
{
  const uint32_t lr = uint32_t(ctx.lr);
  if ((lr != kSpawnLookupFfa && lr != kSpawnLookupTeam) || !BracketOn(base))
  {
    __imp__sub_82424AF0(ctx, base);
    return;
  }
  const uint32_t duel = ctx.r3.u32;
  if (!g_br.built)
  {
    PPCContext saved = ctx;
    BuildCells(saved, base); // Rare switched every laser on just before (82424D00)
  }
  if (g_br.place.empty())
  {
    __imp__sub_82424AF0(ctx, base);
    return;
  }
  const int rot = int(Load32(base, duel + kDuelRotation));
  const int pair = (int(ctx.r4.u32) - rot + 5) % 5;
  const int side = int(ctx.r5.u32);
  const int cell = g_br.place[size_t((pair + g_br.round - 1) % int(g_br.place.size()))];
  const std::vector<int> &areas = g_br.cells[size_t(cell)].areas;
  // Side 0 and 1 get two different areas of the arena, as far apart in its list as it allows.
  const size_t pick = (size_t(side & 1) * (areas.size() / 2) + size_t(side >> 1)) % areas.size();
  const int area = areas[pick];
  int arena = -1, slot = -1;
  for (int a = 0; a < 5 && arena < 0; ++a)
  {
    for (int s = 0; s < 4; ++s)
    {
      if (int(Load32(base, kArenaTable + uint32_t(a * 4 + s) * 4)) == area)
      {
        arena = a;
        slot = s;
        break;
      }
    }
  }
  if (arena < 0)
  {
    __imp__sub_82424AF0(ctx, base);
    return;
  }
  if (Log())
  {
    REXLOG_INFO("pdz_scenario: Duel bracket: pair {} side {} -> {} area {} (arena {} slot {}; Rare asked arena {} slot {})",
                pair, side, g_br.cells[size_t(cell)].name, area, arena, slot, ctx.r4.u32, ctx.r5.u32);
  }
  ctx.r4.u64 = uint32_t(arena);
  ctx.r5.u64 = uint32_t(slot);
  __imp__sub_82424AF0(ctx, base);
}

// sub_8259D168 (laser, dt): the laser's update, where Rare's touch-to-drop runs.
REX_HOOK_RAW(sub_8259D168)
{
  const uint32_t laser = ctx.r3.u32;
  PPCContext saved = ctx;
  t_duel_laser = laser;
  __imp__sub_8259D168(ctx, base);
  t_duel_laser = 0;
  if (g_br.touch_pending && g_br.touch_laser == laser)
  {
    g_br.touch_pending = false;
    if (const DuelLaser *l = FindDuelLaser(laser))
    {
      Store32(base, l->setup, g_br.touch_group); // Rare's group drop was skipped for this touch
      if (Load32(base, laser + kLaserState) == 2)
      {
        DropBorder(saved, base, laser, g_br.touch_char, "Rare's touch");
      }
    }
  }
}

// sub_8259DAB8 (laser): the laser's draw (colour per viewer).
REX_HOOK_RAW(sub_8259DAB8)
{
  t_duel_laser = ctx.r3.u32;
  __imp__sub_8259DAB8(ctx, base);
  t_duel_laser = 0;
}

// sub_82550CA0 (character, key): does the character hold this key? Asked by the laser's touch (8259D8B8) and its
// colour (8259DC40): with the bracket, a key holder may open only his zone's border, and only those show green.
REX_HOOK_RAW(sub_82550CA0)
{
  const uint32_t lr = uint32_t(ctx.lr);
  const uint32_t who = ctx.r3.u32;
  __imp__sub_82550CA0(ctx, base);
  if ((lr != kKeyAskTouch && lr != kKeyAskColour) || !t_duel_laser || !PdzDuelMatch(base))
  {
    return;
  }
  const bool key = ctx.r3.u32 & 0xFF;
  const DuelLaser *l = g_br.on ? FindDuelLaser(t_duel_laser) : nullptr;
  const bool allowed = key && (!g_br.on || (l && OpenableFor(*l, base, who)));
  if (lr == kKeyAskColour && Log() && (REXCVAR_GET(pdz_test_duel_key) || key) && g_br.colour_logged.size() < 200 &&
      g_br.colour_logged.emplace(t_duel_laser, who).second)
  {
    bool participant = false;
    for (uint32_t p = Load32(base, kParticipantList), n = 0; IsGuestPointer(p) && n < 64; p = Load32(base, p + 4), ++n)
    {
      participant = participant || Load32(base, p + kParticipantCharacter) == who;
    }
    const uint32_t setup = Load32(base, t_duel_laser + kPropSetup);
    const bool real = IsGuestPointer(setup);
    REXLOG_INFO("pdz_scenario: Duel gate colour: laser {:08X} (group {}, +144 {}, +145 {}; sides {} / {}) for viewer "
                "{:08X} (vtable {:08X}, {}a participant's character): key 1 {}, bracket {} -> {}",
                t_duel_laser, real ? Load32(base, setup) : 0, real ? base[setup + 144] : 0, real ? base[setup + 145] : 0,
                l ? ZoneName(l->part[0]) : std::string("?"), l ? ZoneName(l->part[1]) : std::string("?"), who,
                IsGuestPointer(who) ? Load32(base, who) : 0, participant ? "" : "NOT ", key ? "yes" : "no",
                g_br.on ? (allowed ? "openable" : "shut") : "off",
                allowed && real && !base[setup + 144] && base[setup + 145] ? "GREEN" : "red");
  }
  if (!g_br.on || !key)
  {
    return;
  }
  if (!allowed)
  {
    ctx.r3.u64 = 0; // shut to him: Rare treats him as having no key (and draws the laser red)
    return;
  }
  if (lr == kKeyAskTouch && l)
  {
    // Rare drops this laser now; its group drop (setup +0 > 0, 8259D930) is skipped: the bracket drops the
    // border's other lasers one by one (DropBorder, after the update).
    g_br.touch_pending = true;
    g_br.touch_laser = t_duel_laser;
    g_br.touch_char = who;
    g_br.touch_group = Load32(base, l->setup);
    Store32(base, l->setup, 0);
  }
}

// sub_82424FD0 (duel): Duel's tick (vtable +12). The bracket's per-frame work after Rare's.
REX_HOOK_RAW(sub_82424FD0)
{
  const uint32_t duel = ctx.r3.u32;
  PPCContext saved = ctx;
  __imp__sub_82424FD0(ctx, base);
  if (duel != g_br.duel || !BracketOn(base))
  {
    return;
  }
  const int phase = int(Load32(base, duel + kDarkOpsPhase));
  const auto now = std::chrono::steady_clock::now();
  const auto since = [&now](std::chrono::steady_clock::time_point t) {
    return std::chrono::duration<double>(now - t).count();
  };
  if (phase != g_br.phase)
  {
    if (phase == 2)
    {
      g_br.phase2_at = now;
    }
    g_br.phase = phase;
  }
  if (phase != 2)
  {
    return;
  }
  // Holstered players stay unarmed (Rare's put-away; draws refused while fresh, kHolsterStale).
  for (const uint32_t c : g_br.holstered)
  {
    if (!objective_bots::CharacterDown(saved, base, c))
    {
      PdzProtectionUnarmBot(saved, base, c, "Duel bracket: holstered winner");
    }
  }
  if (now < g_br.next_scan)
  {
    return;
  }
  g_br.next_scan = now + std::chrono::milliseconds(500);
  if (!g_br.built)
  {
    BuildCells(saved, base);
  }
  int on = 0;
  for (const DuelLaser &l : g_br.lasers)
  {
    on += LaserUp(base, l);
  }
  const bool lasers_changed = on != g_br.lasers_on;
  g_br.lasers_on = on;
  // Who is where, alive; the zones.
  std::vector<uint32_t> revived;
  const std::vector<DuelMember> members = Members(saved, base, revived);
  Rezone(base, members, true);
  g_br.part_of.clear();
  g_br.home_of.clear();
  g_br.side_of.clear();
  for (const DuelMember &m : members)
  {
    g_br.side_of[m.character] = m.side;
    if (m.home >= 0)
    {
      g_br.home_of[m.character] = ZoneOfCell(m.home);
    }
    if (m.here >= 0)
    {
      g_br.part_of[m.character] = ZoneOfCell(m.here);
    }
  }
  if (lasers_changed && Log())
  {
    REXLOG_INFO("pdz_scenario: Duel bracket: lasers {} of {} on: {}", on, g_br.lasers.size(), ZoneList());
  }
  // The pairs at the fight's start (after the buy phase): who is where, and how far apart.
  if (!g_br.start_logged && Log())
  {
    g_br.start_logged = true;
    for (size_t i = 0; i < g_br.parts.size(); ++i)
    {
      const DuelPart &z = g_br.parts[i];
      std::string pairs;
      for (size_t a = 0; a < z.chars.size(); ++a)
      {
        for (size_t b = a + 1; b < z.chars.size(); ++b)
        {
          if (g_br.side_of[z.chars[a]] != g_br.side_of[z.chars[b]])
          {
            pairs += fmt::format("{}{} vs {}: {:.1f} m apart", pairs.empty() ? "" : ", ", NameOf(base, z.chars[a]),
                                 NameOf(base, z.chars[b]), Distance(base, z.chars[a], z.chars[b]) / 100.0f);
          }
        }
      }
      if (!z.chars.empty())
      {
        REXLOG_INFO("pdz_scenario: Duel bracket: round {} at the fight's start: zone {} {}: {}", g_br.round, i, z.name,
                    pairs.empty() ? fmt::format("{} player(s) of one side", z.chars.size()) : pairs);
      }
    }
  }
  // The round's last 60 s: every key-openable laser drops, nobody is holstered (Rare's timer ends the round).
  const uint32_t settings = Load32(base, kMatchSettings);
  const int minutes = IsGuestPointer(settings) ? base[settings + kSettingsRoundMinutes] : 0;
  if (!g_br.backstop && minutes > 0 && since(g_br.phase2_at) >= minutes * 60.0 - kBackstopSeconds)
  {
    g_br.backstop = true;
    int dropped = 0;
    for (const DuelLaser &l : g_br.lasers)
    {
      if (!l.nokey && LaserUp(base, l))
      {
        Call(saved, base, sub_8259DE48, l.prop, 0);
        ++dropped;
      }
    }
    for (const DuelMember &m : members)
    {
      DuelReleaseBot(saved, base, m.character);
    }
    if (Log())
    {
      REXLOG_INFO("pdz_scenario: Duel bracket: round {}: backstop: the last {:.0f} s ({} min round): all {} remaining lasers "
                  "dropped, everyone draws",
                  g_br.round, kBackstopSeconds, minutes, dropped);
    }
  }
  // Decisions (one line each), with the winner's gates: every keyed laser of his zone's border goes green. A win is
  // new when its side was last seen fighting (an empty zone joined later doesn't make a second one).
  for (size_t i = 0; i < g_br.parts.size(); ++i)
  {
    DuelPart &z = g_br.parts[i];
    if (!z.decided)
    {
      g_br.undecided_since.emplace(z.key, now);
      for (const int side : z.sides)
      {
        g_br.fighting[side] = true;
      }
      continue;
    }
    g_br.undecided_since.erase(z.key);
    for (const uint32_t c : z.chars)
    {
      g_br.hunting.erase(c);
    }
    if (z.winner >= 0)
    {
      // Kept decided only after a real fight (the winner was seen fighting): a player not located on the first scan
      // can still reopen his zone when he is found.
      const auto f = g_br.fighting.find(z.winner);
      if (f != g_br.fighting.end() && f->second)
      {
        g_br.sticky[z.key] = z.winner;
      }
    }
    if (z.kept && g_br.kept_logged.insert(z.key).second && Log())
    {
      REXLOG_INFO("pdz_scenario: Duel zone {} {} stays decided (winner side {}): more than one side counted again", i,
                  z.name, z.winner);
    }
    if (!z.arena)
    {
      continue;
    }
    bool fresh = false;
    if (z.winner >= 0)
    {
      const auto f = g_br.fighting.find(z.winner);
      fresh = f == g_br.fighting.end() || f->second;
      g_br.fighting[z.winner] = false;
      if (fresh)
      {
        g_br.won_at[z.winner] = now;
        g_br.auto_done.erase(z.winner);
      }
    }
    else
    {
      for (const int c : z.cells)
      {
        fresh = (g_br.cells[size_t(c)].arena >= 0 && g_br.empty_logged.insert(c).second) || fresh;
      }
    }
    if (!fresh || !Log())
    {
      continue;
    }
    std::string who;
    uint32_t winner = 0;
    for (const uint32_t c : z.chars)
    {
      who += (who.empty() ? "" : ", ") + NameOf(base, c);
      winner = winner ? winner : c;
    }
    int expected = 0, green = 0;
    const std::string border = BorderOf(base, int(i), &expected);
    for (const DuelLaser &l : g_br.lasers)
    {
      green += winner && OpenableFor(l, base, winner);
    }
    REXLOG_INFO("pdz_scenario: Duel zone {} {} decided: {}{}; border: {}{}", i, z.name,
                z.winner >= 0 ? fmt::format("winner side {}", z.winner) : std::string("empty"),
                who.empty() ? "" : " (" + who + ")", border,
                z.winner >= 0 ? fmt::format("; key taken -> lasers green for him: {} of {}", green, expected) : std::string());
  }
  // Backstop: a winner still behind keyed border lasers 20 s after his win gets them all dropped (log 285: his gates
  // never became openable). Once per win.
  for (size_t i = 0; i < g_br.parts.size() && !g_br.backstop; ++i)
  {
    const DuelPart &z = g_br.parts[i];
    const auto won = z.decided && z.winner >= 0 ? g_br.won_at.find(z.winner) : g_br.won_at.end();
    if (won == g_br.won_at.end() || since(won->second) < kAutoDropSeconds || g_br.auto_done.count(z.winner))
    {
      continue;
    }
    g_br.auto_done.insert(z.winner);
    int dropped = 0;
    for (const DuelLaser &l : g_br.lasers)
    {
      if (!l.nokey && LaserUp(base, l) && OnBorderOf(l, int(i)))
      {
        Call(saved, base, sub_8259DE48, l.prop, 0);
        ++dropped;
      }
    }
    if (dropped && Log())
    {
      REXLOG_INFO("pdz_scenario: Duel bracket: backstop: zone {} {}: the winner (side {}) still behind {} keyed border "
                  "laser(s) {:.0f} s after his win: all dropped",
                  i, z.name, z.winner, dropped, kAutoDropSeconds);
    }
  }
  // Holsters: the players of decided zones (a winner who walks into an undecided zone draws again) and the revived.
  g_br.holstered.clear();
  if (!g_br.backstop)
  {
    for (const DuelPart &z : g_br.parts)
    {
      if (!z.decided)
      {
        continue;
      }
      for (const uint32_t c : z.chars)
      {
        const auto here = g_br.part_of.find(c);
        if (here == g_br.part_of.end() || g_br.parts[size_t(here->second)].decided)
        {
          g_br.holstered.insert(c);
        }
      }
    }
    g_br.holstered.insert(revived.begin(), revived.end());
  }
  // Holstered bot winners walk to their nearest openable gate (Rare's goal 4) and open it on arrival. No progress
  // for 8 s: a new path; for 16 s: the gate opens where he stands (no safe way to move a character is known).
  for (const uint32_t c : g_br.holstered)
  {
    if (!IsBot(base, c))
    {
      continue;
    }
    const auto home = g_br.home_of.find(c);
    const int mine = home == g_br.home_of.end() ? -1 : home->second;
    const DuelLaser *best = nullptr;
    float best_d = kNoDistance;
    uint32_t best_pad = 0;
    for (const DuelLaser &l : g_br.lasers)
    {
      const int s = l.part[0] == mine ? 0 : 1;
      if (OpenableFor(l, base, c) && l.pad[s])
      {
        const float d = Distance(base, c, l.prop);
        if (d < best_d)
        {
          best_d = d;
          best = &l;
          best_pad = l.pad[s];
        }
      }
    }
    if (!best)
    {
      if (g_br.gate.count(c))
      {
        DuelReleaseBot(saved, base, c);
      }
      continue;
    }
    const float dx = LoadFloat(base, c + kPosition) - LoadFloat(base, best->prop + kPosition);
    const float dz = LoadFloat(base, c + kPosition + 8) - LoadFloat(base, best->prop + kPosition + 8);
    const float to_pad = FlatToPad(base, c, best_pad);
    // Arrived: at the pad he was sent to (2 m), or within the beam's half length of the laser (log 120).
    if (std::sqrt(dx * dx + dz * dz) < kGateReach || to_pad < 200.0f)
    {
      DropBorder(saved, base, best->prop, c, "on arrival");
      continue;
    }
    const auto g = g_br.gate.find(c);
    if (g == g_br.gate.end() || g->second.laser != best->prop)
    {
      g_br.going_home.erase(c);
      GateWalk w;
      w.laser = best->prop;
      w.pad = best_pad;
      w.best = to_pad;
      w.progress = now;
      g_br.gate[c] = w;
      WalkTo(saved, base, c, best_pad);
      if (Log())
      {
        REXLOG_INFO("pdz_scenario: Duel bracket: bot {} walks to gate {:08X} (group {}, {:.1f} m, to {}) on Rare's goal 4, "
                    "pad {:08X}",
                    NameOf(base, c), best->prop, best->group, best_d / 100.0f,
                    ZoneName(best->part[0] == mine ? best->part[1] : best->part[0]), best_pad);
      }
      continue;
    }
    GateWalk &w = g->second;
    if (to_pad < w.best - 100.0f)
    {
      w.best = to_pad;
      w.progress = now;
    }
    const double stuck = since(w.progress);
    if (stuck >= kGateStuck)
    {
      if (Log())
      {
        REXLOG_INFO("pdz_scenario: Duel bracket: backstop: bot {} made no progress to gate {:08X} for {:.0f} s ({:.1f} m "
                    "from its pad): the gate opens where he stands",
                    NameOf(base, c), w.laser, kGateStuck, to_pad / 100.0f);
      }
      DropBorder(saved, base, w.laser, c, "stuck, opened where he stood");
    }
    else if (stuck >= kGateRepath && !w.repathed)
    {
      w.repathed = true;
      WalkTo(saved, base, c, w.pad);
      if (Log())
      {
        REXLOG_INFO("pdz_scenario: Duel bracket: bot {} made no progress to gate {:08X} for {:.0f} s ({:.1f} m from its "
                    "pad): a new path",
                    NameOf(base, c), w.laser, kGateRepath, to_pad / 100.0f);
      }
    }
  }
  // Bots stay in their zone while a duel is on (theirs or the one they wandered into): back to the nearest spawn pad
  // of their home arena.
  for (const DuelMember &m : members)
  {
    const uint32_t c = m.character;
    if (!IsBot(base, c) || g_br.backstop || g_br.hunting.count(c) || g_br.gate.count(c))
    {
      continue;
    }
    const int home = ZoneOfCell(m.home), here = ZoneOfCell(m.here);
    const bool away = home >= 0 && here >= 0 && here != home &&
                      (!g_br.parts[size_t(home)].decided || !g_br.parts[size_t(here)].decided);
    if (!away)
    {
      if (g_br.going_home.erase(c))
      {
        g_br.gate_pad.erase(c);
        objective_bots::SetGoal(saved, base, c, objective_bots::kGoalRoam, 0);
      }
      continue;
    }
    if (g_br.going_home.count(c))
    {
      continue;
    }
    uint32_t pad = 0;
    float near = kNoDistance;
    for (const int area : g_br.cells[size_t(m.home)].areas)
    {
      for (const uint32_t p : AreaPads(base, area))
      {
        if (FlatToPad(base, c, p) < near)
        {
          near = FlatToPad(base, c, p);
          pad = p;
        }
      }
    }
    if (!pad)
    {
      continue;
    }
    g_br.going_home.insert(c);
    WalkTo(saved, base, c, pad);
    if (Log())
    {
      REXLOG_INFO("pdz_scenario: Duel bracket: bot {} strayed into {} during a duel: back to {} (pad {:08X}, {:.1f} m)",
                  NameOf(base, c), ZoneName(here), ZoneName(home), pad, near / 100.0f);
    }
  }
  // A human out of his undecided zone (log 298: he wandered off): his zone's bots hunt after 15 s.
  std::unordered_set<std::string> left;
  for (const DuelMember &m : members)
  {
    const int home = ZoneOfCell(m.home), here = ZoneOfCell(m.here);
    if (!IsBot(base, m.character) && home >= 0 && here >= 0 && here != home && !g_br.parts[size_t(home)].decided)
    {
      const std::string &key = g_br.parts[size_t(home)].key;
      left.insert(key);
      if (g_br.left_since.emplace(key, now).second && Log())
      {
        REXLOG_INFO("pdz_scenario: Duel bracket: {} left {} for {} while its duel is on: its bots hunt him after {:.0f} s",
                    NameOf(base, m.character), ZoneName(home), ZoneName(here), kLeftSeconds);
      }
    }
  }
  for (auto it = g_br.left_since.begin(); it != g_br.left_since.end();)
  {
    it = left.count(it->first) ? std::next(it) : g_br.left_since.erase(it);
  }
  // Stalls: a zone undecided for 60 s (15 s with its human out) puts its bots on Rare's hunt goal at the nearest enemy.
  for (size_t i = 0; i < g_br.parts.size() && !g_br.backstop; ++i)
  {
    const DuelPart &z = g_br.parts[i];
    const auto stall = g_br.undecided_since.find(z.key);
    const auto out = g_br.left_since.find(z.key);
    const bool stalled = stall != g_br.undecided_since.end() && since(stall->second) >= kStallSeconds;
    const bool gone = out != g_br.left_since.end() && since(out->second) >= kLeftSeconds;
    if (z.decided || (!stalled && !gone))
    {
      continue;
    }
    for (const uint32_t c : z.chars)
    {
      if (!IsBot(base, c) || g_br.hunting.count(c))
      {
        continue;
      }
      uint32_t enemy = 0;
      float best = kNoDistance;
      for (const uint32_t o : z.chars)
      {
        if (g_br.side_of[o] != g_br.side_of[c] && Distance(base, c, o) < best)
        {
          best = Distance(base, c, o);
          enemy = o;
        }
      }
      if (enemy)
      {
        g_br.going_home.erase(c);
        g_br.gate_pad.erase(c);
        g_br.hunting.insert(c);
        objective_bots::SetGoal(saved, base, c, objective_bots::kGoalAttackCarrier, enemy);
        if (Log())
        {
          REXLOG_INFO("pdz_scenario: Duel bracket: zone {} {} {}: bot {} hunts {} (Rare's goal 3, {:.1f} m)", i, z.name,
                      gone ? fmt::format("its human out for {:.0f} s", kLeftSeconds)
                           : fmt::format("undecided for {:.0f} s", kStallSeconds),
                      NameOf(base, c), NameOf(base, enemy), best / 100.0f);
        }
      }
    }
  }
}

// Goal 4's pad for a bot walking to his gate (the sub_8241D690 hook).
uint32_t PdzDuelGatePad(uint32_t character)
{
  const auto it = g_br.gate_pad.find(character);
  return it == g_br.gate_pad.end() ? 0 : it->second;
}

// sub_8253C8A0 [bot, other]: Rare's "same side?" test for bots (the enemy pick 82539388, the shoot step 821C30C0
// and the rest). In a team game (82147A90) it compares teams (8251CC10). DarkOps is always a team game, so in free
// for all Duel (Rare's own team count 0: everyone on team 0) every bot took every other bot for a team mate and
// none fought (log 115: two bots 3.4 m apart for 60 s, Rare's hunt goal included). Duel free for all: any two
// different characters are enemies, as Rare's Duel means it (its constructor's "0 teams"). Team Duel keeps Rare's
// test. Genuine fix inside the Duel mode (pdz_mp_cut_scenarios_duel, off by default).
REX_EXTERN(__imp__sub_8253C8A0);

REX_HOOK_RAW(sub_8253C8A0)
{
  if (ctx.r3.u32 != ctx.r4.u32 && PdzDuelFreeForAll(base))
  {
    ctx.r3.u64 = 0;
    return;
  }
  __imp__sub_8253C8A0(ctx, base);
}

// sub_8251EBD0 [object, other]: Rare's "friend?" test, which bot perception uses (its sense callback 8257F620):
// owner links first, then the two objects' team bit masks (+128 / +130, set at spawn). Free for all Duel (Rare's
// team count 0) gives everyone team 0's bit, so no bot ever sensed another as an enemy: logs 116-119, bots fired
// only at the human (every hit on him, none on a bot) and two bots stood 1.1 m apart all round. Duel free for all:
// two different characters are never friends; the owner links (a character's own projectiles) stay Rare's. Genuine
// fix inside the Duel mode (pdz_mp_cut_scenarios_duel, off by default).
REX_EXTERN(__imp__sub_8251EBD0);

REX_HOOK_RAW(sub_8251EBD0)
{
  constexpr uint32_t kHumanVtable = 0x820C7DE0;
  const uint32_t a = ctx.r3.u32, b = ctx.r4.u32;
  __imp__sub_8251EBD0(ctx, base);
  if (!(ctx.r3.u32 & 0xFF) || a == b || !IsGuestPointer(a) || !IsGuestPointer(b) || !PdzDuelFreeForAll(base))
  {
    return;
  }
  const uint32_t va = Load32(base, a), vb = Load32(base, b);
  if ((va == kBotVtable || va == kHumanVtable) && (vb == kBotVtable || vb == kHumanVtable))
  {
    ctx.r3.u64 = 0;
  }
}

// sub_82187D18 (character): Rare's team lists. Each MP writer of a character's team bits (+128, one bit per team)
// calls it straight after, and it files the character under each bit it has: the bot constructor 82537AC8, the
// player's MP spawn 825A96E0 and the participant's team value change 824746C8. How Killcount makes everyone an
// enemy: nobody has a team bit. The player gets one only when the match's team option (settings +876) is above 1,
// and Duel's constructor sets it to 0 in free for all, so Duel players already had none; bots get one when the bot
// table's team-game byte (82147A90, byte 0) is set, and DarkOps sets it for every scenario, so in Duel free for all
// every bot had team 0's bit. That is the only difference from Killcount. Every bit test then took two bots for
// friends: the friend test 8251EBD0 (also for what a character fires, which copies his bits at launch, 82532028 /
// 825320D8), the same-side test 8253C8A0 (which wants exactly one bit), the hit handler's own test (82549040) and
// the contact test (82545D70). The two hooks above cover two characters only; log 273 (both in: Haybot and
// Countbatula hit each other, then stood 9 m apart for 1.5 min on Rare's hunt goal) sent us after the rest. Duel
// free for all: a character keeps no team bit, as in Killcount, so every one of those tests answers as Rare's free
// for all does. Team Duel, the owner links (a character's own projectiles) and the participants' teams (8251CC10:
// scores, round end, the bracket) stay Rare's. Not hot (team changes and spawns only). Genuine fix inside the Duel
// mode (pdz_mp_cut_scenarios_duel, off by default).
REX_EXTERN(__imp__sub_82187D18);

REX_HOOK_RAW(sub_82187D18)
{
  constexpr uint32_t kHumanVtable = 0x820C7DE0;
  constexpr uint32_t kTeamBits = 128; // character: team bit mask (16 bits)
  const uint32_t c = ctx.r3.u32;
  if (IsGuestPointer(c) && (base[c + kTeamBits] | base[c + kTeamBits + 1]) != 0)
  {
    const uint32_t vt = Load32(base, c);
    if ((vt == kBotVtable || vt == kHumanVtable) && PdzDuelFreeForAll(base))
    {
      base[c + kTeamBits] = 0;
      base[c + kTeamBits + 1] = 0;
    }
  }
  __imp__sub_82187D18(ctx, base);
}
